function camMat(e,root){let M=new DOMMatrix();for(let n=e;n&&n!==root&&n.transform;n=n.parentNode){const L=n.transform.baseVal;
  for(let i=L.numberOfItems-1;i>=0;i--){const m=L.getItem(i).matrix;M=new DOMMatrix([m.a,m.b,m.c,m.d,m.e,m.f]).multiply(M)}}return M}
