  if(z>1)svg.setAttribute("viewBox",`${F(vx)} ${F(vy)} ${F(vw)} ${F(vh)}`);
  const img=el.querySelector("img.L-bg");if(g&&img)img.src=bgURI(g,vx,vy,vw,vh,Math.min(.8,(z-1)*1.25)/z);
  el.querySelectorAll(".L-post .lt").forEach(d=>{const [x,y,rx,ry]=d.dataset.g.split(" ").map(Number);
    d.style.left=F((x-rx-vx)/vw*100)+"%";d.style.top=F((y-ry-vy)/vh*100)+"%";d.style.width=F(2*rx/vw*100)+"%";d.style.height=F(2*ry/vh*100)+"%"});
