  const backH=`<path d="M-14.6 -20 C-24 -19 -24 -7 -14.6 -7" stroke="${ln}" stroke-width="4.6" fill="none" stroke-linecap="round"/><path d="M-14.6 -20 C-24 -19 -24 -7 -14.6 -7" stroke="${b}" stroke-width="2.6" fill="none" stroke-linecap="round"/>`;
  const flw=`<g transform="translate(-2 -12.5)">${[0,72,144,216,288].map(a=>`<ellipse cx="0" cy="-2.6" rx="1.7" ry="2.5" fill="#FFF6E0" transform="rotate(${a})"/>`).join("")}<circle r="1.5" fill="#F6B73C"/></g><g transform="translate(7 -9) scale(.6)">${[0,72,144,216,288].map(a=>`<ellipse cx="0" cy="-2.6" rx="1.7" ry="2.5" fill="#FFD0DC" transform="rotate(${a})"/>`).join("")}<circle r="1.5" fill="#F6B73C"/></g>`;
  const top=`${EL(0,-24.4,13.6,3,dk(b,.55))}${EL(0,-24,11,2,dk(b,.7))}<path d="M-13.6 -24.4 A13.6 3 0 0 0 13.6 -24.4" stroke="${l}" stroke-width="1.4" fill="none"/><path d="M-13.6 -24.4 A13.6 3 0 0 1 13.6 -24.4" stroke="${ln}" stroke-width="1" fill="none"/>`;
  const can=`${backH}${spout}${rose}${V(P1(body),b,{dark:d,line:ln,lw:1.2,sx:3.5,sy:2,hl:`<path d="M-10.5 -21 C-12 -15 -12 -9 -10.5 -5" stroke="#fff" stroke-width="2.2" fill="none" stroke-linecap="round" opacity=".55" filter="${u("soft2")}"/>`})}
    <path d="M-15 -17.2 C-6 -15.6 6 -15.6 15 -17.2" stroke="${dk(b,.15)}" stroke-width="1.6" fill="none" opacity=".6"/>${flw}${[-11,-5,1,7,12].map(x=>`<circle cx="${x}" cy="-21.6" r=".6" fill="${ln}" opacity=".6"/>`).join("")}${top}${handle}`;
