  const drops=Array.from({length:14},(_,i)=>{const j=(i*5)%6,dur=.7+((i*13)%5)*.06,bg=f1(-((i*.29)%dur)),r=2+((i*7)%5)*.1;
    return `<g opacity="0"><path d="M${f1(r*.9)} 0 C${f1(r*.9)} ${f1(r*.7)} ${f1(r*.2)} ${f1(r)} ${f1(-r*.3)} ${f1(r*.8)} L${f1(-r*1.5)} 0 L${f1(-r*.3)} ${f1(-r*.8)} C${f1(r*.2)} ${f1(-r)} ${f1(r*.9)} ${f1(-r*.7)} ${f1(r*.9)} 0Z" fill="#8FD0F4" stroke="#3F8FC4" stroke-width=".45"/><circle cx="${f1(r*.2)}" cy="${f1(-r*.35)}" r="${f1(r*.3)}" fill="#fff" opacity=".9"/><animateMotion path="${ST6[j]}" rotate="auto" dur="${f1(dur)}s" begin="${bg}s" repeatCount="indefinite"/><animate attributeName="opacity" values="0;1;1;0" keyTimes="0;.06;.88;1" dur="${f1(dur)}s" begin="${bg}s" repeatCount="indefinite"/></g>`}).join("");
