  const sprout=crack+`<g transform="translate(12.7 -16.4)">${ST("M0 0 C1.6 -1.6 1.8 -4.6 3.6 -7.6",G.stem,1.3)}<path d="M-.8 .6 C.2 -.4 .8 -.8 1.4 -.6" stroke="#2E1808" stroke-width="1.4" fill="none" stroke-linecap="round"/>${leafG(3.6,-7.4,6.4,2.8,26,G.leafL,{lw:.6})}${leafG(3.2,-6.2,5.4,2.3,-58,G.leaf,{lw:.6})}</g>`;
