/* =============== YUMAK (yün yumağı, flyable) =============== */
function yarn(c){const b=col6(c,"#EE6F9C"),d=dk(b,.3),ln=dk(b,.5),l=lt(b,.35),id=uid("yn"),R=10.6,cy=-R;
  const fam=(a,ks)=>ks.map(k=>`<ellipse cx="0" cy="${cy}" rx="${R}" ry="${k}" fill="none" stroke="${d}" stroke-width=".9" transform="rotate(${a} 0 ${cy})"/><ellipse cx="0" cy="${f1(cy-.6)}" rx="${R}" ry="${k}" fill="none" stroke="${l}" stroke-width=".55" opacity=".85" transform="rotate(${a} 0 ${cy})"/>`).join("");
  const tail=`${ST("M8.4 -3.6 C14 -1.6 16 1 20 .2 C23.4 -.4 24 -3 21.6 -3.8 C19.4 -4.4 18.6 -1.4 22 -.4 C24.6 .3 27 .2 29 -.4",ln,1.7)}${ST("M8.4 -3.6 C14 -1.6 16 1 20 .2 C23.4 -.4 24 -3 21.6 -3.8 C19.4 -4.4 18.6 -1.4 22 -.4 C24.6 .3 27 .2 29 -.4",b,1)}`;
  return `${cshadow(3,.4,13,1.8,.24)}${tail}<defs><clipPath id="${id}"><circle cx="0" cy="${cy}" r="${R}"/></clipPath></defs>${V(E1(0,cy,R,R),b,{dark:d,line:0,sx:2.4,sy:2.4})}
   <g clip-path="url(#${id})">${fam(-35,[2.6,5.4,8.2])}<g>${fam(55,[3.4,6.6])}</g><path d="M-8 -16 C-4 -12 0 -10.6 6 -11" stroke="${d}" stroke-width="1" fill="none"/><path d="M-9.4 -12.6 C-5 -8.6 -1 -6.4 5 -5" stroke="${l}" stroke-width=".7" fill="none"/></g>
   <circle cx="0" cy="${cy}" r="${R}" fill="none" stroke="${ln}" stroke-width="1.1"/>${HL(-4,-15,3.2,1.8,.55,-30)}`}
PROPS.yumak=o=>FLY(o,yarn(o.color),"Yün yumağı",13,-10);
PROPS.yumak.meta={name:"Yün yumağı",h:21,demoS:2.4,note:"Sarılmış iplik dokulu yün yumağı, yerde kıvrılan ucu sağa uzanır. flyable (collect/sort, kedi oyunu). o.color yün rengi (varsayılan pembe)."};

/* =============== KARAHİNDİBA (stateful: on = pamuk tohum başı, off = üflenmiş, tohumlar uçuyor) =============== */
const DL="#6DA848";
function dLeaf(L,a,k=1){const c=DL,ln=dk(c,.5);
  const d="M0 0 C2.6 -1.6 4.4 -2.6 5.6 -2.2 L5 -4.8 L8.6 -3.2 C9.8 -3.6 10.8 -4.2 11.8 -4 L11.4 -6.6 L15 -4.4 C16.6 -4.2 18.4 -3.4 20 -2 C21 -1 21 0 20 .4 C17.6 1.4 15.4 2 13.4 2 L14.2 4.4 L10.4 2.6 C9.2 2.8 8 3 7 2.8 L7.6 5 L4 2.6 C2.6 2 1 1.2 0 0Z";
  return `<g transform="rotate(${a}) scale(${f1(L/20)} ${f1(k*L/20)})">${FP(d,c,`stroke="${ln}" stroke-width="${f1(.7*20/L)}" stroke-linejoin="round"`)}${ST("M.6 0 C7 -.6 14 -.4 19.6 -1",lt(c,.4),f1(.8*20/L),.85)}${FP("M0 0 C4 1.2 8 2.4 13.4 2 C9 2.8 4 2.4 0 0Z",dk(c,.2),'opacity=".5"')}</g>`}
function seedTuft(x,y,r,n=7,a0=0,col="#FFFFFF"){let d="";for(let i=0;i<n;i++){const a=a0+i/n*Math.PI*2;d+=`M${f1(x)} ${f1(y)} L${f1(x+Math.cos(a)*r)} ${f1(y+Math.sin(a)*r)} `}return d}
function puff(){const R=13,cy=-45;let rays="",tips="",dotsI="";
  for(let i=0;i<64;i++){const a=i*2.39996,rr=R*(.62+((i*5)%7)/7*.38),x=Math.cos(a)*rr,y=cy+Math.sin(a)*rr*.96;
    rays+=`M0 ${cy} L${f1(x*.9)} ${f1(cy+(y-cy)*.9)} `;tips+=seedTuft(x,y,2.3,7,a);}
  return `<circle cx="0" cy="${cy}" r="${R+1}" fill="#FFFFFF" opacity=".22" filter="${u("soft2")}"/><circle cx="0" cy="${cy}" r="${R*.8}" fill="#F4F7FA" opacity=".5"/>
   <path d="${rays}" stroke="#AEB9C6" stroke-width=".5" opacity=".9"/><path d="${tips}" stroke="#8E9BAA" stroke-width=".9" opacity=".5" stroke-linecap="round"/><path d="${tips}" stroke="#FFFFFF" stroke-width=".55" stroke-linecap="round"/>
   <circle cx="-4" cy="${cy-4}" r="5" fill="#fff" opacity=".45" filter="${u("soft2")}"/>${EL(0,cy,1.7,1.5,"#C9B27E",'opacity=".85"')}`}
function flySeed(x,y,a,k=1){const tip=`M0 -6 `+seedTuft(0,-6,2.8,8,-Math.PI/2,"#fff").slice(0);
  return `<g transform="translate(${f1(x)} ${f1(y)}) rotate(${a}) scale(${k})"><path d="M0 0 L0 -6" stroke="#B7AE9E" stroke-width=".4"/><ellipse cx="0" cy=".8" rx=".55" ry="1.3" fill="#8A6A3E"/><path d="${seedTuft(0,-6,2.8,8,0)}" stroke="#8E9BAA" stroke-width=".9" opacity=".45" stroke-linecap="round"/><path d="${seedTuft(0,-6,2.8,8,0)}" stroke="#fff" stroke-width=".55" stroke-linecap="round"/></g>`}
function dandelion(o,blown){const cy=-45;
  const stalk=stem(`M0 0 C1.6 -12 -1.6 -26 0 ${blown?-41:-43}`,1.5,"#7DB35A");
  const rosette=`<g transform="translate(0 0)">${dLeaf(17,-160,1)}${dLeaf(19,-20,1)}${dLeaf(14,-128,.9)}${dLeaf(15,-50,.9)}${dLeaf(12,-95,.8)}</g>`;
  if(o.flower&&!blown){const pet=(n,r,c,dy)=>Array.from({length:n},(_,i)=>`<path transform="rotate(${f1(i*360/n+dy)})" d="M-.9 0 L-.7 ${-r} Q0 ${-r-1.1} .7 ${-r} L.9 0Z" fill="${c}" stroke="#C98E1E" stroke-width=".3"/>`).join("");
    return `${stalk}${rosette}${ST(`M-2 ${cy+6} l-3 3.4 M2 ${cy+6} l3 3.4 M0 ${cy+6} l0 4`,"#5E9E3E",1)}<g transform="translate(0 ${cy})">${pet(22,9.4,"#F6C742",0)}${pet(18,7,"#FFD95A",8)}${pet(12,4.6,"#FFE27A",4)}<circle r="1.8" fill="#F2B42E"/>${HL(-3,-3,3,1.6,.4)}</g>`}
  if(!blown)return `${stalk}${rosette}${puff()}`;
  /* üflenmiş: çıplak tabla + birkaç kalan tohum + rüzgârla uçup giden tohumlar */
  const bare=`${[[-.4,-3,-60],[.6,-3,40],[-2.4,-1,-100]].map(([x,y,a])=>flySeed(x,cy+y+1,a,.9)).join("")}${V(E1(0,cy+1.6,3.2,2.6),"#C7A86A",{dark:"#8A6E3E",line:"#5E4A28",lw:.6,sx:.8,sy:.8,hl:[[-1.2,-.4],[.6,-.8],[1.4,.6],[-.2,.8]].map(([x,y])=>`<circle cx="${x}" cy="${cy+1.6+y}" r=".4" fill="#7E6436"/>`).join("")})}${ST(`M-2.6 ${cy+3.4} l-1.6 1.8 M2.6 ${cy+3.4} l1.6 1.8 M0 ${cy+4} v2`,"#5E9E3E",.7)}`;
  const flying=Array.from({length:8},(_,i)=>{const sx=4+((i*5)%4)*2,sy=cy-6+((i*7)%9)-4,ex=38+((i*11)%5)*6,ey=cy-26-((i*13)%7)*3,dur=4.2+(i%3)*.8,bg=-(i*.62).toFixed(2);
    return `<g>${flySeed(0,0,-20+(i%4)*14,.9+(i%3)*.1)}<animateTransform attributeName="transform" type="translate" values="${sx} ${sy};${f1((sx+ex)/2)} ${f1((sy+ey)/2+6)};${ex} ${ey}" dur="${dur}s" begin="${bg}s" repeatCount="indefinite"/><animate attributeName="opacity" values="0;1;1;0" keyTimes="0;.1;.75;1" dur="${dur}s" begin="${bg}s" repeatCount="indefinite"/></g>`}).join("");
  const still=[[10,cy-8,-24],[18,cy-16,10],[26,cy-10,-8],[14,cy-24,20]].map(([x,y,a])=>flySeed(x,y,a,1)).join("");
  return `${stalk}${rosette}${bare}<g>${still}</g>${flying}`}
PROPS.karahindiba=o=>PL(o,`<rect x="-18" y="-62" width="36" height="64" fill="transparent"/>`+stateful(o,dandelion(o,true),dandelion(o,false)),"Karahindiba",14);
PROPS.karahindiba.meta={name:"Karahindiba",h:60,states:["on","off"],demoS:1.7,note:"Dişli yaprak rozeti + ince sap. state on (varsayılan) = beyaz pamuk tohum topu (paraşüt tohumlar); state:'off' = üflenmiş: çıplak tabla, birkaç kalan tohum, rüzgârla sağa-yukarı süzülen paraşüt tohumlar (animasyonlu). Dokununca üflenmesi için state:'on' + toggle; restore ile off→on. o.flower:true (yalnız on) sarı çiçek açmış karahindiba. Tohumlar sağa uçar; flip:true sola."};

