  const sh="M0 -21.2 C4.2 -25.4 13.2 -23 13.2 -12.2 C13.2 -4.4 7.2 0 0 0 C-7.2 0 -13.2 -4.4 -13.2 -12.2 C-13.2 -23 -4.2 -25.4 0 -21.2Z";
