  const milk="M-7 -17 C-7.9 -15.9 -8.3 -14.6 -8.3 -13 V-2.4 C-8.3 -1 -6.2 -.5 0 -.5 C6.2 -.5 8.3 -1 8.3 -2.4 V-13 C8.3 -14.6 7.9 -15.9 7 -17Z";
