/* tüylü havuç yaprağı: sap + iki tonlu küçük yaprakçıklar */
const frond=(p0,c1,c2,p1,sz=1,g1="#5FAE44",g2="#3E8E36")=>{const P=t=>bz(p0,c1,c2,p1,t);let s=`<path d="M${p0.map(f1).join(" ")} C${c1.map(f1).join(" ")} ${c2.map(f1).join(" ")} ${p1.map(f1).join(" ")}" stroke="#3B7A2C" stroke-width="${f1(.75*sz)}" fill="none" stroke-linecap="round"/>`;
  [.3,.46,.6,.73,.85].forEach((t,i)=>{const p=P(t),q=P(t+.03),a=Math.atan2(q[1]-p[1],q[0]-p[0]),L=(2.9-t*1.5)*sz;
    [-1,1].forEach(sd=>{const aa=a+sd*.95,cx=p[0]+Math.cos(aa)*L*.52,cy=p[1]+Math.sin(aa)*L*.52,d=f1(aa*180/Math.PI);
      s+=`<ellipse cx="${f1(cx)}" cy="${f1(cy)}" rx="${f1(L*.56)}" ry="${f1(L*.3)}" fill="${(i+(sd>0?1:0))%2?g1:g2}" transform="rotate(${d} ${f1(cx)} ${f1(cy)})"/>`})});
  const e=P(1),q=P(.96),a=Math.atan2(e[1]-q[1],e[0]-q[0])*180/Math.PI;
  return s+`<ellipse cx="${f1(e[0])}" cy="${f1(e[1])}" rx="${f1(1.5*sz)}" ry="${f1(.8*sz)}" fill="${g1}" transform="rotate(${f1(a)} ${f1(e[0])} ${f1(e[1])})"/>`};
D.havuc=o=>{const b="#F28A2E",ln="#A8501A";
  const body=`${V("M-5.4 -22 C-6 -14 -3.2 -6 0 0 C3.2 -6 6 -14 5.4 -22 C4.6 -24.6 -4.6 -24.6 -5.4 -22Z",b,{dark:"#C8621C",line:ln,lw:1.1,sx:2,sy:2,hl:HL(-2.4,-16,1.1,4.4,.55)})}
   ${[[-18.6,1,1.6],[-15.2,-1,1.4],[-11.8,1,1.2],[-8.4,-1,1],[-5,1,.8]].map(([y,sd,w])=>`<path d="M${f1(sd*(5.6+y*.18))} ${y} q${f1(-sd*w*.7)} ${f1(-.2)} ${f1(-sd*w*1.5)} ${f1(.6)}" stroke="${ln}" stroke-width=".7" fill="none" stroke-linecap="round" opacity=".7"/>`).join("")}
   <path d="M-4.2 -12 l-1.6 .6 M3.4 -7.4 l1.5 .5 M-2.2 -4.4 l-1.2 .7" stroke="${ln}" stroke-width=".4" opacity=".6" stroke-linecap="round"/>
   <path d="M-2.6 -23.8 C-1 -24.8 1 -24.8 2.6 -23.8" stroke="#6A8A2A" stroke-width="1.2" fill="none" stroke-linecap="round"/>`;
  if(o.planted){
    /* kabarık toprak tümseği: ufalanan üst kenar (tümsek), iki ton kahve */
    const mound=(w,h,n,amp,y0=.4)=>{let d=`M${-w} ${y0}`;for(let i=1;i<=n;i++){const t=i/n,x=-w+2*w*t,y=y0-h*Math.sin(Math.PI*t)**.7,xm=-w+2*w*(t-.5/n),ym=y0-h*Math.sin(Math.PI*(t-.5/n))**.7-amp*(.6+HZ(i)*.8);d+=` Q${f1(xm)} ${f1(ym)} ${f1(x)} ${f1(y)}`}return d+"Z"};
    const soil=`<path d="${mound(15.6,5.2,13,1.1)}" fill="#6E4526" stroke="#4A2C16" stroke-width=".9" stroke-linejoin="round"/><path d="${mound(13.6,4.6,11,.9,-.6)}" fill="#8A5A34"/><path d="M-9 -3.6 C-5 -5 3 -5.2 8 -4" stroke="#A8764A" stroke-width="1" fill="none" stroke-linecap="round" opacity=".8"/>`;
    const crumbs=[[-11,-2.4,1],[-7,-3.6,.8],[-2.6,-4.2,.7],[3,-4.3,.9],[7.8,-3.4,.8],[11.4,-2,1],[-4.8,-1.6,.6],[5.6,-1.4,.7],[0,-2.4,.6]].map(([x,y,r],i)=>`<circle cx="${x}" cy="${y}" r="${r}" fill="${i%2?"#A8764A":"#8E6038"}"/><circle cx="${f1(x-.2)}" cy="${f1(y-.3)}" r="${f1(r*.4)}" fill="#C0906A" opacity=".7"/>`).join("");
    const pebbles=`<ellipse cx="-13.4" cy="-.6" rx="1.6" ry="1" fill="#B9B4AC" stroke="#7E776E" stroke-width=".5"/><ellipse cx="13" cy="-.4" rx="1.2" ry=".8" fill="#CFC9BF" stroke="#8A8378" stroke-width=".5"/>`;
    const grass=`<path d="M-15.6 .2 C-16 -2.6 -17.2 -4.4 -18.6 -5.2 C-17 -3.4 -16.6 -1.8 -16.6 .2Z M-15 .2 C-14.8 -3 -14 -5 -12.8 -6.2 C-13.4 -4.2 -14 -2 -14 .2Z M-16.4 .2 C-17.6 -1.6 -19.4 -2.4 -20.6 -2.4 C-19 -1.4 -18 -.6 -17.4 .2Z" fill="#6DB54B" stroke="#3B7A2C" stroke-width=".4"/>`;
    const lv=frond([-1,-10],[-4,-14],[-8.4,-17],[-12,-21],1)+frond([1,-10],[4,-14.6],[8.4,-17.4],[11.6,-21.6],1)+frond([-.4,-10.4],[-1.6,-15],[-3.2,-20],[-3.6,-25.4],1.05)+frond([.4,-10.4],[1.8,-15.4],[3.4,-19.8],[4.6,-25],1.05)+frond([0,-10.6],[-.2,-15],[.2,-21],[.6,-27.4],1.1,"#6FBE50","#4E9E3C");
    return `${SH(16,.25,2.4)}${lv}${V("M-6.4 -1.6 C-6.8 -8.4 -4 -11.2 0 -11.2 C4 -11.2 6.8 -8.4 6.4 -1.6Z",b,{dark:"#C8621C",line:ln,lw:1.1,sx:2,sy:1.5,hl:HL(-2.6,-8,1.3,1.8,.6)})}
     <path d="M-6.2 -6.8 q.9 .5 1.9 .3 M4.4 -3.8 q.9 .1 1.7 -.4" stroke="${ln}" stroke-width=".7" fill="none" stroke-linecap="round" opacity=".7"/><path d="M-2 -10.8 C-.8 -11.6 .8 -11.6 2 -10.8" stroke="#6A8A2A" stroke-width="1.1" fill="none" stroke-linecap="round"/>
     ${soil}${crumbs}${pebbles}${grass}`}
  /* yatık: gövde karnı yere değer (76°); yapraklar sağa uzanır, biri yere sarkar */
  const L=[3.3,-7.3],lv=frond(L,[8,-9.8],[13,-13.4],[19.6,-15.4],1)+frond(L,[9,-7.4],[15,-6.6],[22.2,-8],1.05,"#6FBE50","#4E9E3C")+frond(L,[8,-5],[13.6,-1.4],[19.8,-.8],1)+frond(L,[6,-11.6],[8.6,-16],[11.4,-19.6],.9);
  return `${cshadow(-1,0,17,2.2,.26)}${cshadow(-6,-.2,9,1.4,.2)}${lv}<g transform="translate(-20 -1.5) rotate(76)">${body}</g>`};
