    +[0,1,2,3,4,5].map(i=>{const top=-10.6+HZ(i)*.9;return tuft(10.55+i*1.9,top,i%2?"#FFFFFF":"#9ED8F6",i%2?"#A9B8C8":"#4E9CC8")+`<path d="M${f1(10.25+i*1.9)} ${f1(top+1.2)} V-7" stroke="#fff" stroke-width=".3" opacity=".8"/>`}).join("");
