D.sabun=o=>{const c=col(o.color,"#F59AB8"),ln=dk(c,.45),seed=Math.abs(Math.round(o.x||0));
  const [ir,ird]=LG([[0,"#FFB8D8"],[.35,"#B8E8FF"],[.7,"#FFF3A8"],[1,"#C8B8FF"]],0,0,1,1);
  const bub=(x,y,r,cls)=>`<g ${cls||""}><circle cx="${f1(x)}" cy="${f1(y)}" r="${f1(r)}" fill="#EAF6FF" fill-opacity=".35" stroke="${ir}" stroke-width="${f1(Math.max(.6,r*.22))}"/><circle cx="${f1(x)}" cy="${f1(y)}" r="${f1(r)}" fill="none" stroke="#8FB8D8" stroke-width=".3" opacity=".7"/><path d="M${f1(x-r*.6)} ${f1(y-r*.1)} A${f1(r*.62)} ${f1(r*.62)} 0 0 1 ${f1(x-r*.05)} ${f1(y-r*.62)}" stroke="#fff" stroke-width="${f1(Math.max(.4,r*.2))}" fill="none" stroke-linecap="round" opacity=".95"/></g>`;
  /* köpük: çok boy (r 1–5) kabarcık, ince açık mavi kenar; arkadakiler önce */
  const FB=[[-9.4,-13.2,4.6],[-4.2,-14.4,3.8],[-12.8,-11.4,3],[-7,-17.4,2.8],[-1.2,-12.2,2.4],[-6.6,-10.8,2.6],[-11.6,-15.8,1.9],[-3,-17.8,1.7],[.8,-14.8,1.5],[-14,-13.8,1.3],[-9.6,-9.8,1.6],[-2.2,-10.4,1.2],[-5,-19.6,1.1],[1.8,-11.8,1]];
  const foam=FB.map(([x,y,r])=>`<circle cx="${x}" cy="${y}" r="${r}" fill="#FFFFFF" stroke="#A8CDE8" stroke-width="${f1(Math.min(.55,.25+r*.07))}"/><path d="M${f1(x-r*.55)} ${f1(y-r*.15)} A${f1(r*.6)} ${f1(r*.6)} 0 0 1 ${f1(x-r*.05)} ${f1(y-r*.6)}" stroke="#DDEFFA" stroke-width="${f1(Math.max(.3,r*.14))}" fill="none" stroke-linecap="round"/><ellipse cx="${f1(x+r*.25)}" cy="${f1(y+r*.35)}" rx="${f1(r*.55)}" ry="${f1(r*.35)}" fill="#D6E8F5" opacity=".6"/>`).join("");
  const rise=[[-4,-22,2.4,0],[5,-18,1.8,2.4],[-10,-23,1.5,4.2],[9,-24,2.6,1.2]].map(([x,y,r,d])=>`<g class="mote" pointer-events="none" style="animation-duration:5.5s;animation-delay:${f1(-d-(seed%3))}s">${bub(x,y,r)}</g>`).join("");
  return `${SH(15,.26,2.2)}${ird}<ellipse cx="1" cy="-.2" rx="18.6" ry="2.8" fill="#BFE3F7" opacity=".5"/><path d="M-13 .8 C-6 1.8 8 1.8 15 .6" stroke="#fff" stroke-width=".6" fill="none" opacity=".7"/><circle cx="-16.4" cy=".6" r=".7" fill="#BFE3F7" opacity=".7"/><circle cx="17.6" cy="-.4" r=".5" fill="#BFE3F7" opacity=".7"/>
   ${V("M-14 -5.4 C-14 -10.6 -10.8 -11.8 0 -11.8 C10.8 -11.8 14 -10.6 14 -5.4 L14 -3.4 C14 -.6 10.8 0 0 0 C-10.8 0 -14 -.6 -14 -3.4Z",c,{sx:2,sy:2,lw:1.1})}
   <path d="M-12.4 -6.6 C-12.4 -9.8 -10 -10.4 0 -10.4 C10 -10.4 12.4 -9.8 12.4 -6.6 C12.4 -4.6 10 -4.2 0 -4.2 C-10 -4.2 -12.4 -4.6 -12.4 -6.6Z" fill="${lt(c,.28)}" stroke="${dk(c,.15)}" stroke-width=".6"/>
   <path d="${heartD(5.4,-7.2,1.5)}" fill="${dk(c,.12)}" opacity=".7"/><path d="${heartD(5.2,-7.5,1.5)}" fill="none" stroke="#fff" stroke-width=".4" opacity=".7"/>
   <path d="M1.6 -9.6 C5.6 -10 9.4 -9.6 11.2 -8" stroke="#fff" stroke-width="1" fill="none" opacity=".8" stroke-linecap="round"/><path d="M10.2 -5.4 C11 -5.8 11.6 -6.4 11.8 -7" stroke="#fff" stroke-width=".6" fill="none" opacity=".7" stroke-linecap="round"/>
   <ellipse cx="-6.6" cy="-9" rx="8.4" ry="1.7" fill="#1B1A2E" opacity=".2" filter="${u("soft2")}"/>
   ${foam}${bub(10.4,-15.4,2.6)}${bub(13.8,-10.6,1.4)}${bub(7.4,-18.8,1)}${bub(-15.6,-18.6,.9)}${rise}`};
