   +`<path d="${cap}" fill="${dk(b,.1)}"/><path d="M11 -4.8 C13.6 -4.6 16.6 -4.2 18.4 -3.2 L18.4 -2.2 H10 C9.9 -3 10.2 -4.2 11 -4.8Z" fill="${d}" opacity=".6"/><path d="${cap}" fill="none" stroke="${ln}" stroke-width=".85" stroke-linejoin="round"/><path d="M10.9 -6.9 C13.8 -6.4 16.6 -5.4 17.6 -3.8" stroke="${lt(b,.55)}" stroke-width=".8" fill="none" stroke-linecap="round"/><ellipse cx="14.2" cy="-5.9" rx="1.8" ry=".6" fill="#fff" opacity=".45" transform="rotate(14 14.2 -5.9)"/>`
