  let knA="";for(let i=0;i<NA-1;i+=2)[-2.2,2.2].forEach((off,k)=>{knA+=V_(atA(i,off-.9,-.6+k*.5),atA(i,off,.6+k*.5),atA(i,off+.9,-.6+k*.5))});
  let knB="";for(let t=tS+.6;t<LB-.6;t+=1.7)[-2.2,2.2].forEach(off=>{knB+=V_(atB(t-.6,off-.9),atB(t+.6,off),atB(t-.6,off+.9))});
