  const fringe=(q,dir,nn)=>Array.from({length:6},(_,j)=>{const off=(j-2.5)*1.5,ext=3+(j%2)*.9,q0=[q[0]+nn[0]*off,q[1]+nn[1]*off],q1=[q0[0]+dir[0]*ext+(j%3-1)*.3,q0[1]+dir[1]*ext];return `<path d="M${P(q0)} L${P(q1)}" stroke="${ln}" stroke-width="1.15" stroke-linecap="round"/><path d="M${P(q0)} L${P(q1)}" stroke="${j%2?c:s2}" stroke-width=".55" stroke-linecap="round"/>`}).join("");
  const n0=[-TA[0][1],TA[0][0]];
  const edgeHL=`<path d="M${Array.from({length:NA-1},(_,i)=>P(atA(i,-W/2+.7))).join(" L")}" stroke="#fff" stroke-width=".7" fill="none" opacity=".35"/>`;
  const crease=`<path d="M${P(Ep)} L${P(Em)}" stroke="${lt(c,.45)}" stroke-width="1.3" stroke-linecap="round" opacity=".8"/>`;
  const thick=(band,cc)=>`<path d="${band}" fill="${cc}" transform="translate(0 1.1)"/><path d="${band}" fill="none" stroke="${ln}" stroke-width=".9" stroke-linejoin="round" transform="translate(0 1.1)"/>`;
  const inner=cshadow(0,-.4,26,3.6,.2)+`<path d="${bandA}" fill="#1B1A2E" opacity=".25" transform="translate(.3 1.8)" filter="${u("soft2")}"/>`+thick(bandA,dk(c,.35))
    +fringe(CA[0],[-TA[0][0],-TA[0][1]],n0)
    +V(P1(bandA),c,{dark:d,line:0,sx:1.2,sy:1.8,op:.5})+stA+knit(knA)+edgeHL+ST(`M${P(atA(14,W/2-.8))} Q${P(atA(15,0,1.4))} ${P(atA(16,-W/2+.8))} M${P(atA(34,W/2-.8))} Q${P(atA(35,0,-1.2))} ${P(atA(36,-W/2+.8))}`,d,.7,.4)+`<path d="${bandA}" fill="none" stroke="${ln}" stroke-width=".9" stroke-linejoin="round"/>`
