/* ---------- YAPBOZ PARÇASI (flyable) ---------- */
/* kenar üretici: A→B kenarı; tip t(ab çıkıntı) | h(girinti) | f(düz). Boyun ±2.6, baş r 4.2, derinlik ≈7.2 */
function pzEdge(A,B,t){if(t==="f")return `L${f1(B[0])} ${f1(B[1])}`;
  const dx=B[0]-A[0],dy=B[1]-A[1],Lh=Math.hypot(dx,dy),tx=dx/Lh,ty=dy/Lh,nx=ty*(t==="t"?1:-1),ny=-tx*(t==="t"?1:-1),m=Lh/2;
  const p=(u,v)=>`${f1(A[0]+tx*u+nx*v)} ${f1(A[1]+ty*u+ny*v)}`,r=4.2,c=r*.5523,hc=3;
  return `L${p(m-2.8,0)} C${p(m-2.4,1)} ${p(m-4.4,1.4)} ${p(m-r,hc)} C${p(m-r,hc+c)} ${p(m-c,hc+r)} ${p(m,hc+r)} C${p(m+c,hc+r)} ${p(m+r,hc+c)} ${p(m+r,hc)} C${p(m+4.4,1.4)} ${p(m+2.4,1)} ${p(m+2.8,0)} L${p(Lh,0)}`}
