  if(k.st==="pig")front=`<path d="M${X(-6.6)} ${Y(.6)} C${X(-7.6)} ${Y(-9.4)} ${X(7.6)} ${Y(-9.4)} ${X(6.6)} ${Y(.6)} C${X(5.4)} ${Y(-3.4)} ${X(1.6)} ${Y(-4.6)} ${X(0)} ${Y(-3.2)} C${X(-1.6)} ${Y(-4.6)} ${X(-5.4)} ${Y(-3.4)} ${X(-6.6)} ${Y(.6)}Z" fill="${H}" stroke="${Hl}" stroke-width="${w(.9)}"/><circle cx="${X(-6.4)}" cy="${Y(-.6)}" r="1.25" fill="${k.tie}" stroke="${dk(k.tie,.4)}" stroke-width="${w(.6)}"/><circle cx="${X(6.4)}" cy="${Y(-.6)}" r="1.25" fill="${k.tie}" stroke="${dk(k.tie,.4)}" stroke-width="${w(.6)}"/>`;
  if(k.st==="curly")front=[200,222,245,268,292,316,340].map((a,i)=>{const t=a*Math.PI/180;return `<circle cx="${X(Math.cos(t)*5.4)}" cy="${Y(-1.2+Math.sin(t)*5)}" r="${i%2?2.5:2.8}" fill="${H}" stroke="${Hl}" stroke-width="${w(.8)}"/>`}).join("")+`<path d="M${X(-5.6)} ${Y(-1)} C${X(-5.6)} ${Y(-6.4)} ${X(5.6)} ${Y(-6.4)} ${X(5.6)} ${Y(-1)} C${X(3)} ${Y(-3)} ${X(-3)} ${Y(-3)} ${X(-5.6)} ${Y(-1)}Z" fill="${H}"/>`;
  if(k.st==="bob")front=`<path d="M${X(-6.5)} ${Y(-.4)} C${X(-6.8)} ${Y(-8.2)} ${X(6.8)} ${Y(-8.2)} ${X(6.5)} ${Y(-.4)} C${X(5.6)} ${Y(-2.4)} ${X(4.6)} ${Y(-2.6)} ${X(3.4)} ${Y(-2.6)} L${X(-3.4)} ${Y(-2.6)} C${X(-4.6)} ${Y(-2.6)} ${X(-5.6)} ${Y(-2.4)} ${X(-6.5)} ${Y(-.4)}Z" fill="${H}" stroke="${Hl}" stroke-width="${w(.9)}"/><path d="M${X(-6.3)} ${Y(-3)} C${X(-5.8)} ${Y(-9.4)} ${X(5.8)} ${Y(-9.4)} ${X(6.3)} ${Y(-3)}" stroke="${k.band}" stroke-width="1.7" fill="none" stroke-linecap="round"/><path d="M${X(-4.6)} ${Y(-6.2)} C${X(-2.8)} ${Y(-8)} ${X(0)} ${Y(-8.4)} ${X(1.6)} ${Y(-8.3)}" stroke="#fff" stroke-width=".55" fill="none" opacity=".7" stroke-linecap="round"/>`;
  if(k.st==="short"||k.st==="tuft")front=`<path d="M${X(-6.6)} ${Y(0)} C${X(-7.4)} ${Y(-9)} ${X(7)} ${Y(-9.6)} ${X(6.6)} ${Y(-.4)} C${X(5)} ${Y(-4)} ${X(1)} ${Y(-5.2)} ${X(-2.4)} ${Y(-3.6)} C${X(-4)} ${Y(-2.8)} ${X(-5.8)} ${Y(-2)} ${X(-6.6)} ${Y(0)}Z" fill="${H}" stroke="${Hl}" stroke-width="${w(.9)}"/>`+(k.st==="tuft"?`<path d="M${X(-.6)} ${Y(-6.6)} C${X(-1)} ${Y(-9.6)} ${X(1.4)} ${Y(-10.4)} ${X(2.6)} ${Y(-9.4)} C${X(1.4)} ${Y(-9)} ${X(1)} ${Y(-8)} ${X(1.4)} ${Y(-6.6)}Z" fill="${H}" stroke="${Hl}" stroke-width="${w(.8)}"/>`:"");
  if(k.st==="bun")front=`<path d="M${X(-6.6)} ${Y(.4)} C${X(-7.6)} ${Y(-9.2)} ${X(7.6)} ${Y(-9.2)} ${X(6.6)} ${Y(.4)} C${X(4.6)} ${Y(-3.8)} ${X(-4.6)} ${Y(-3.8)} ${X(-6.6)} ${Y(.4)}Z" fill="${H}" stroke="${Hl}" stroke-width="${w(.9)}"/>`;
