  const torso=`<path d="M${X(-8.4)} ${Y(17)} C${X(-8.4)} ${Y(8.6)} ${X(-5)} ${Y(6.6)} ${X(0)} ${Y(6.6)} C${X(5)} ${Y(6.6)} ${X(8.4)} ${Y(8.6)} ${X(8.4)} ${Y(17)}Z" fill="${k.shirt}" stroke="${dk(k.shirt,.45)}" stroke-width="${w(.9)}"/><path d="M${X(-2.4)} ${Y(6.8)} Q${X(0)} ${Y(8.6)} ${X(2.4)} ${Y(6.8)}" stroke="${lt(k.shirt,.5)}" stroke-width="${w(1.2)}" fill="none"/><path d="M${X(-6.8)} ${Y(10)} C${X(-7)} ${Y(12)} ${X(-7)} ${Y(14)} ${X(-6.6)} ${Y(16)}" stroke="${dk(k.shirt,.2)}" stroke-width="1.2" fill="none" opacity=".5"/>`;
