  s+=wins.map(x=>`<path d="${winD(x)}" fill="${gf}" opacity=".16"/><path d="M${x+2.2} -70 L${x+7.4} -86 L${x+10.4} -86 L${x+4.2} -68Z" fill="#fff" opacity=".42"/><path d="M${x+19.6} -64.6 L${x+23.4} -75 L${x+24.6} -75 L${x+21} -64.6Z" fill="#fff" opacity=".3"/>${pth(winD(x),"none",L,W(1.6))}`).join("");
