  s+=ln("M61 -16 A17 17 0 0 0 27 -16 M-39 -16 A17 17 0 0 0 -73 -16",dk(c,.45),W(2.8),.8);
  if(!city)s+=`${pth(rr(50,-106,34,9,2.5),"#FFFFFF","#C8302A",W(1.6))}${[57,65,74].map((x,i)=>`<circle cx="${x}" cy="${-103.4+(i===1?.6:0)}" r="1.2" fill="#3A3F52"/><path d="M${x} ${-102+(i===1?.6:0)} v2.6 M${x-1.2} ${-99.2+(i===1?.6:0)} l1.2 -1 l1.2 1" stroke="#3A3F52" stroke-width="1" fill="none" stroke-linecap="round"/>`).join("")}${ln("M56 -97 V-98 M78 -97 V-98","#4E5668",W(1.8))}`;
  // şeritler kapıda kesilir
  const seg=(y1,y2)=>[[-95,63.8],[84.3,106]].map(([a,b])=>`M${a} ${y1} H${b}`).join(" ");
  if(!city)s+=ln(seg(-48)+" "+seg(-38),dk(c,.62),W(3.4),.85)+ln([[-95,63.8],[84.3,105.8]].map(([a,b])=>`M${a} -48.9 H${b} M${a} -38.9 H${b}`).join(" "),lt(c,.35),W(1.1),.6);
  else s+=[[-95.6,63.8],[84.3,106.6]].map(([a,b])=>`<path d="M${a} -44 H${b} V-36 H${a}Z" fill="${lt(c,.25)}" opacity=".9"/>`).join("")+ln(seg(-44),dk(c,.3),W(1.1),.6);
  s+=`<rect x="-95" y="-94" width="5" height="4" rx="1.5" fill="#F0833A"/><rect x="95" y="-96" width="5" height="3.6" rx="1.5" fill="#F0833A"/>`;
  // tamponlar: gövde köşesini sarar, en fazla ~2 birim taşar, koyu alt dudak
  const bR="M-78 -27.4 H-95.2 C-97.4 -27.4 -98.2 -26 -98.2 -23.6 V-19.6 C-98.2 -17.2 -96.8 -15.4 -93.6 -15.4 H-75.4 C-75.6 -19.8 -76.6 -24 -78 -27.4Z";
  const bF="M85.6 -27.4 H105.8 C107.8 -27.4 108.6 -26 108.6 -23.6 V-19.6 C108.6 -17.2 107.2 -15.4 104 -15.4 H85.6 C85 -19.4 85 -23.4 85.6 -27.4Z";
  s+=V(bR,"#646B82",{dark:dk("#646B82",.35),line:dk("#646B82",.45),lw:W(1.3),sx:1,sy:1.5})+V(bF,"#646B82",{dark:dk("#646B82",.35),line:dk("#646B82",.45),lw:W(1.3),sx:1,sy:1.5});
  s+=`<path d="M-97.8 -19.4 H-75.6 V-15.6 H-93.6 C-96.4 -15.6 -97.8 -17 -97.8 -19.4Z M85.2 -19.4 H108.2 C108.2 -17 106.8 -15.6 104 -15.6 H85.3Z" fill="${dk("#5A6074",.4)}" opacity=".8"/>${ln("M-96 -25.8 H-79 M87 -25.8 H106",lt("#5A6074",.45),W(1.1),.75)}`;
  s+=`<circle cx="104.6" cy="-36" r="8" fill="#FFF3B8" opacity=".35" filter="${u("soft2")}"/><ellipse cx="104.4" cy="-36" rx="2.4" ry="4.2" fill="#FFF6D2" stroke="${L}" stroke-width="${W(1.3)}"/><ellipse cx="103.9" cy="-37.4" rx=".8" ry="1.4" fill="#fff"/><rect x="-97.5" y="-37" width="4" height="8" rx="1.5" fill="#E4433A" stroke="${L}" stroke-width="${W(1.1)}"/>`;
  s+=ln("M102.6 -86 L111 -88 L111 -74",L,W(2.2))+pth(rr(108,-82,6,11,2.5),"#5A6074",dk("#5A6074",.45),W(1.2))+`<path d="M109.4 -80.4 V-73.4" stroke="#B8C6DA" stroke-width="${W(1.3)}" stroke-linecap="round"/>`;
