  fl+=`<rect x="-40" y="${Y0}" width="480" height="8" fill="${LG([[0,"#1E2A38",.25],[1,"#1E2A38",0]])}"/><rect x="60" y="197" width="112" height="4" fill="#1E1428" opacity=".25" filter="${u("soft2")}"/>`;

  /* ---------- IŞIK ---------- */
