  let amb=`<g class="curt" style="animation-duration:9s"><path d="${curt}" fill="url(#${cp})"/><path d="${curt}" fill="${LG([[0,"#3A6A8A",.22],[.4,"#fff",0],[.7,"#3A6A8A",.14],[1,"#fff",.1]],1,0)}"/>${[378,386,394].map(x=>`<path d="M${x} 20 Q${x+2} 80 ${x-2} 148" stroke="#8AAAC0" stroke-width="1" fill="none" opacity=".5"/>`).join("")}<path d="${curt}" fill="none" stroke="#8AAAC0" stroke-width="1"/></g>`;
  amb+=`<rect x="198" y="14" width="210" height="3.4" rx="1.7" fill="#D4D9E0" stroke="#6A7282" stroke-width=".7"/><circle cx="198" cy="15.7" r="3" fill="#E0E4EA" stroke="#6A7282" stroke-width=".7"/>${[372,378,384,390,396,402].map(x=>`<circle cx="${x}" cy="18" r="2.4" fill="none" stroke="#9AA4B4" stroke-width="1"/>`).join("")}`;
