  if(ev)toTop(`<rect x="-40" y="-40" width="480" height="320" fill="#2A1A48" opacity=".1"/><ellipse cx="${MX}" cy="70" rx="140" ry="110" fill="#FFB060" opacity=".08" filter="${u("b12")}"/>`);
  if(nt)toTop(`<rect x="-40" y="-40" width="480" height="320" fill="#141C4A" opacity=".14"/>`);
