  const winQ=`M170 110 L186 111.6 L186 131 L170 132Z`;
  s+=`<path d="M167.6 107.4 L188.4 109.4 L188.4 133.6 L167.6 134.6Z" fill="#4E86A0" stroke="#2E5468" stroke-width="1"/><path d="${winQ}" fill="#2A1C16"/><path d="M178 110.8 V131.6 M170 121 L186 121.4" stroke="#4E86A0" stroke-width="1.6"/><path d="M167 135 L189 134 L189.6 136.6 L166.4 137.6Z" fill="${ST[1]}" stroke="${WW[3]}" stroke-width=".7"/>`;
  s+=`<path d="M171 111.6 l5 .5 M171 113 l3 .3" stroke="#8FB8D0" stroke-width=".8" opacity=".6"/>`;
  /* 9b çatının sağ düzlemi: alaturka kiremit */
  const rA=[PX,PY-7],rB=[PX+43,PY-4],rC=[SR+10,STY+6],rD=[FR+10,EY+5];
  const bil=(uu,vv)=>[(1-uu)*(1-vv)*rA[0]+uu*(1-vv)*rB[0]+uu*vv*rC[0]+(1-uu)*vv*rD[0],(1-uu)*(1-vv)*rA[1]+uu*(1-vv)*rB[1]+uu*vv*rC[1]+(1-uu)*vv*rD[1]];
  const Rd=`M${rA} L${rB} L${rC} L${rD}Z`,rid=gid("rf");
  s+=`<clipPath id="${rid}"><path d="${Rd}"/></clipPath><path d="${Rd}" fill="${lgd([[0,TL[1]],[1,TL[2]]],0,0,1,1)}"/>`;
  {let tl="";const N=8,M=9;
   for(let i=0;i<=N;i++){const uu=i/N,a=bil(uu,0),b=bil(uu,1);tl+=`<path d="M${f1(a[0])} ${f1(a[1])} L${f1(b[0])} ${f1(b[1])}" stroke="${TL[3]}" stroke-width=".9" opacity=".55"/>`}
   for(let i=0;i<N;i++){const uu=(i+.5)/N,a=bil(uu,0),b=bil(uu,1);tl+=`<path d="M${f1(a[0])} ${f1(a[1])} L${f1(b[0])} ${f1(b[1])}" stroke="${TL[0]}" stroke-width="1.8" opacity="${i%2?.35:.55}" stroke-linecap="round"/>`}
   for(let j=1;j<M;j++){const vv=j/M;let d="";for(let i=0;i<N;i++){const p=bil(i/N,vv),q=bil((i+1)/N,vv),m=bil((i+.5)/N,vv+.035);d+=(i?"":`M${f1(p[0])} ${f1(p[1])}`)+` Q${f1(m[0])} ${f1(m[1])} ${f1(q[0])} ${f1(q[1])}`}
     tl+=`<path d="${d}" stroke="${TL[3]}" stroke-width=".9" fill="none" opacity=".6"/>`}
   /* saçaktaki kiremit ağızları */
   for(let i=0;i<N;i++){const p=bil((i+.12)/N,1),q=bil((i+.88)/N,1),m=bil((i+.5)/N,.955);tl+=`<path d="M${f1(p[0])} ${f1(p[1])} Q${f1(m[0])} ${f1(m[1])} ${f1(q[0])} ${f1(q[1])}Z" fill="${i%2?TL[3]:"#4A1E16"}" opacity=".85"/>`}
   s+=`<g clip-path="url(#${rid})">${tl}<path d="M${rA} L${rD}" stroke="#fff" stroke-width="5" opacity=".08"/></g>`}
  s+=`<path d="${Rd}" fill="none" stroke="${TL[3]}" stroke-width="1.2" stroke-linejoin="round"/>`;
