  /* mahya (sırt) kiremitleri */
  s+=`<path d="M${rA[0]} ${rA[1]} L${rB[0]} ${rB[1]}" stroke="${TL[3]}" stroke-width="5.4" stroke-linecap="round"/><path d="M${rA[0]} ${rA[1]} L${rB[0]} ${rB[1]}" stroke="${TL[1]}" stroke-width="3.4" stroke-linecap="round"/>`+Array.from({length:6},(_,i)=>{const k=(i+.5)/6,x=rA[0]+(rB[0]-rA[0])*k,y=rA[1]+(rB[1]-rA[1])*k;return `<path d="M${f1(x-2.4)} ${f1(y-1.2)} q2.4 -1.8 4.8 .3" stroke="${TL[0]}" stroke-width=".9" fill="none" opacity=".8"/>`}).join("");
  /* 9c ön cephe (badanalı taş) */
