  [[4,146,20,24],[134,104,15,17],[42,62,9,7],[128,170,12,8]].forEach(([x,y,rx,ry])=>{const pid=gid("fp"),pd=scal(x,y,rx,ry,9,2.2,R);
    s+=`<clipPath id="${pid}"><path d="${pd}"/></clipPath><path d="${pd}" fill="${dk(ST[1],.14)}"/><g clip-path="url(#${pid})">${stoneRows(x-rx-4,y-ry-2,x+rx+4,y+ry+2,6.4,R,ST,"#F4EAD6")}</g><path d="${pd}" fill="none" stroke="${WW[2]}" stroke-width="1.6" opacity=".9"/><path d="${pd}" fill="none" stroke="#fff" stroke-width=".7" opacity=".5" transform="translate(-.8 -.8)"/>`});
