  s+=`<path d="M-20 ${HZ} V96 C-4 90 16 86 36 88 C56 90 74 100 96 110 C104 114 112 116 124 ${HZ}Z" fill="${pal.far}"/><path d="M-20 ${HZ} V104 C10 100 40 102 60 108 C76 112 90 116 100 ${HZ}Z" fill="${pal.far2}"/>`;
  s+=[[6,93.4,1],[16,90.6,.8],[58,90.6,.9],[70,94.6,.75],[82,101.2,.7]].map(([x,y,k])=>umbrellaPine(x,y,k,pal.far2)).join("")+[[26,89.4,4.6],[48,89.6,4]].map(([x,y,rr])=>`<path d="M${x-rr} ${y+1} C${x-rr} ${y-rr*.55} ${x+rr} ${y-rr*.55} ${x+rr} ${y+1}Z" fill="${pal.far2}"/>`).join("");
  if(!sun&&!night)s+=`<path d="M-20 97 C0 91 20 87 36 88.6" stroke="#fff" stroke-width="1.2" fill="none" opacity=".25"/>`;
  s+=lighthouse(38,89);
  if(!(tm==="day"))s+=`<circle cx="38" cy="66.8" r="${night?16:12}" fill="${u("lglow")}" opacity="${night?.8:.7}"/>`;
  s+=`<path d="M338 ${HZ} C350 110 370 106 390 108 C404 109 414 113 424 ${HZ}Z" fill="${pal.isl}"/>`;
  // deniz
  const sea=LG(pal.sea);
  s+=`<rect x="-20" y="${HZ}" width="440" height="80" fill="${sea}"/><rect x="-20" y="${HZ}" width="440" height="1.4" fill="#fff" opacity="${night?.25:.5}"/>`;
  s+=`<path d="M-20 164 C60 160 140 166 220 162 C300 158 340 164 420 160 V200 H-20Z" fill="${pal.shallow}" opacity="${pal.shOp}"/>`;
  for(let i=0;i<46;i++){const y=r(HZ+3,160),x=r(-10,400),w=r(6,22)*(0.5+(y-HZ)/60);s+=`<path d="M${f1(x)} ${f1(y)} h${f1(w)}" stroke="${i%3?(night?"#9FB2E8":"#fff"):sun?"#6A5A8E":night?"#12204A":"#2E7AA4"}" stroke-width="${f1(.6+(y-HZ)/60)}" opacity="${i%3?(night?.18:.35):.3}" stroke-linecap="round"/>`}
  if(sun){let rf="";for(let y=HZ+2;y<176;y+=3.2){const w=6+(y-HZ)*.5+r(-3,3);rf+=`<path d="M${f1(SX-w/2+r(-4,4))} ${f1(y)} h${f1(w)}" stroke="#FFE3A0" stroke-width="${f1(1+(y-HZ)/40)}" opacity="${f1(.75-(y-HZ)/110)}" stroke-linecap="round"/>`}s+=rf}
  if(night){let rf="";for(let y=HZ+2;y<172;y+=3){const w=4+(y-HZ)*.42+r(-3,3);rf+=`<path d="M${f1(MX-w/2+r(-5,5))} ${f1(y)} h${f1(w)}" stroke="#E8E4C4" stroke-width="${f1(.8+(y-HZ)/50)}" opacity="${f1(.6-(y-HZ)/140)}" stroke-linecap="round"/>`}s+=rf;
    s+=`<path d="M38 66.8 L-40 58 L-40 76Z" fill="#FFF3C8" opacity=".08"/><path d="M38 66.8 L120 60 L120 70Z" fill="#FFF3C8" opacity=".06"/>`}
  // ıslak kum (sıcak, parlak) + gökyüzü yansıması + kuru kum
