  s+=`<path d="M-20 180.6 C80 177.6 170 182.6 250 179.6 C320 176.6 370 181.6 420 178.6" stroke="${pal.refl}" stroke-width="1.1" fill="none" opacity=".7"/><path d="M-20 183.4 C90 180.4 180 185 260 182.4 C330 180 372 184 420 181.4" stroke="${pal.refl}" stroke-width=".7" fill="none" opacity=".35"/>`;
  s+=`<g filter="${u("soft2")}"><path d="M-20 190 C70 184 160 192 240 188 C320 184 370 190 420 186 V262 H-20Z" fill="${LG([[0,sandC[0]],[1,sandC[1]]])}"/></g><path d="M-20 194 C70 188 160 196 240 192 C320 188 370 194 420 190 V262 H-20Z" fill="${LG([[0,sandC[0]],[1,sandC[1]]])}"/>`;
  for(let i=0;i<260;i++){const x=r(-10,410),y=r(186,240);s+=`<circle cx="${f1(x)}" cy="${f1(y)}" r="${f1(r(.3,.9))}" fill="${i%3?dk(sandC[1],.25):"#fff"}" opacity="${f1(r(.2,.5))}"/>`}
  for(let i=0;i<14;i++){const x=r(0,380),y=r(198,236);s+=`<path d="M${f1(x)} ${f1(y)} q6 -2 12 0 t12 0" stroke="${dk(sandC[1],.18)}" stroke-width=".9" fill="none" opacity=".45"/>`}
  // ayak izleri (çocuk): denize doğru hafif kıvrılan iz
