  s+=`<path d="M-14 -143 L-15 -153 M-6 -143 L-5.4 -152" stroke="${L}" stroke-width="4" stroke-linecap="round"/><path d="M-14 -143 L-15 -153 M-6 -143 L-5.4 -152" stroke="${Y}" stroke-width="2.3" stroke-linecap="round"/><circle cx="-15" cy="-154" r="2.7" fill="${MN}" stroke="${dk(MN,.35)}" stroke-width=".7"/><circle cx="-5.4" cy="-153" r="2.7" fill="${MN}" stroke="${dk(MN,.35)}" stroke-width=".7"/>`;
  // baş: iri, yuvarlak burunlu
