  s+=`<g clip-path="url(#${hid})"><ellipse cx="-31" cy="-127.5" rx="9" ry="7.6" fill="#FCE4AC"/><ellipse cx="-31" cy="-124" rx="8" ry="3.6" fill="#E9C27E" opacity=".45"/>${spot(-9,-139,2.2)}</g>`;
  s+=`<ellipse cx="-36.4" cy="-129.6" rx=".9" ry="1.2" fill="#8A5A2E"/><ellipse cx="-33.2" cy="-131" rx=".9" ry="1.2" fill="#8A5A2E"/>`;
  s+=`<path d="M-37 -123.6 q3.4 2.8 7.6 .6" stroke="${INK}" stroke-width="1.1" fill="none" stroke-linecap="round"/>`;
  // açık, mutlu göz (irisli)
  s+=`<ellipse cx="-17" cy="-135.4" rx="3.1" ry="3.7" fill="${INK}"/><ellipse cx="-17" cy="-134.2" rx="2.1" ry="1.9" fill="#9A6230" opacity=".9"/><circle cx="-16" cy="-137" r="1.3" fill="#fff"/><circle cx="-17.9" cy="-133.8" r=".55" fill="#fff" opacity=".9"/><path d="M-20.4 -138.6 q3.4 -3.2 7 -.4" stroke="${INK}" stroke-width=".9" fill="none" stroke-linecap="round"/><path d="M-13.8 -138.4 l1.4 -1.2 M-13.4 -136.8 l1.6 -.5" stroke="${INK}" stroke-width=".7" stroke-linecap="round"/>`;
  s+=`<ellipse cx="-22" cy="-127.4" rx="3.6" ry="2.1" fill="#FF8F8F" opacity=".5"/>`;
