  const fy=x=>x<120?100-14*(x+20)/140:x<270?86-12*Math.sin((x-120)/150*Math.PI):74+3*Math.sin(x/30);
  const hc=K.eve?[hill2,mix(hill2,"#9A82B4",.3),mix(hill2,"#5A5088",.4)]:K.rain?["#B8C0CB","#A0AAB8","#C6CCD4"]:["#C9D8E6","#B4C7DA","#D8E2EC"];
