  s+=`<rect x="-20" y="188.2" width="440" height="31" fill="${rd}"/><rect x="-20" y="188.2" width="440" height="3" fill="${SH}" opacity=".16"/>`;
  s+=`<g opacity=".5" filter="${u("soft2")}"><path d="M-20 194 C80 192 200 196 420 193 L420 197 C200 200 80 197 -20 198Z" fill="${T("#5E6676")}" opacity=".35"/><path d="M-20 210 C90 208 220 212 420 209 L420 214 C220 216 90 213 -20 215Z" fill="${T("#5E6676")}" opacity=".35"/></g>`;
  [[30,205,26,5],[196,193,22,4],[372,211,24,5]].forEach(([x,y,w,h])=>s+=`<rect x="${x}" y="${y}" width="${w}" height="${h}" rx="1.5" fill="${T("#7C8494")}" opacity=".55"/><rect x="${x}" y="${y}" width="${w}" height="${h}" rx="1.5" fill="none" stroke="${T("#5E6676")}" stroke-width=".5" opacity=".6"/>`);
  let sp="";for(let i=0;i<150;i++){const x=r(-10,410),y=r(190,218);sp+=`<circle cx="${f1(x)}" cy="${f1(y)}" r="${f1(r(.3,.8))}" fill="${i%2?"#fff":"#1A1030"}" opacity="${f1(r(.06,.16))}"/>`}s+=sp;
  // şerit
  let dl="";for(let x=-8;x<400;x+=36){if(x>250&&x<356)continue;dl+=`M${x} 203.4 h18`}s+=`<path d="${dl}" stroke="${T("#F2EEE2")}" stroke-width="1.6" opacity=".8" stroke-linecap="round"/>`;
  // yaya geçidi (çizgiler yol yönünde, perspektifle kalınlaşır)
  const zb=[[190.8,193.4],[195.6,198.6],[201,204.4],[207,211],[213.6,218]];
  s+=zb.map(([a,b])=>{const t=(a-188)/31,t2=(b-188)/31,xa=272+8*t,xb=338+14*t,xa2=272+8*t2,xb2=338+14*t2;
    return `<path d="M${f1(xa)} ${a} H${f1(xb)} L${f1(xb2)} ${b} H${f1(xa2)}Z" fill="${T("#F6F3EA")}" opacity=".94"/><path d="M${f1(xa)} ${a} H${f1(xb)}" stroke="#fff" stroke-width=".6" opacity=".6"/>`}).join("");
  for(let i=0;i<40;i++){const y=r(190,218),x=r(272,350);s+=`<circle cx="${f1(x)}" cy="${f1(y)}" r="${f1(r(.4,1))}" fill="${T("#8D95A3")}" opacity=".35"/>`}
  // rögar kapağı + ızgara
  s+=`<ellipse cx="138" cy="208" rx="10" ry="3.4" fill="${T("#5E6573")}" stroke="${T("#474D5A")}" stroke-width=".8"/><ellipse cx="138" cy="208" rx="6.6" ry="2.1" fill="none" stroke="${T("#7C8492")}" stroke-width=".7"/><path d="M131 208 h14 M138 205 v6" stroke="${T("#7C8492")}" stroke-width=".5"/>`;
  s+=`<rect x="44" y="189" width="14" height="3.4" rx=".6" fill="${T("#3E4450")}"/><path d="M46.5 189 v3.4 M49 189 v3.4 M51.5 189 v3.4 M54 189 v3.4" stroke="${T("#7C8492")}" stroke-width=".6"/>`;
  // ön kaldırım
  s+=`<rect x="-20" y="218.6" width="440" height="2" fill="${SH}" opacity=".22"/><rect x="-20" y="220" width="440" height="4" fill="${T("#EEE8DC")}"/><path d="M-20 220 H420" stroke="${T("#FFFFFF")}" stroke-width=".8" opacity=".7"/>`;
  let cb2="";for(let x=6;x<420;x+=34)cb2+=`M${x} 220 v4`;s+=`<path d="${cb2}" stroke="${T("#B8AE9E")}" stroke-width=".7"/>`;
  const nw=LG([[0,T(K.rain?"#B3AC9F":"#DDD0BA")],[1,T(K.rain?"#A39C8F":"#CFBFA5")]]);
  s+=`<rect x="-20" y="224" width="440" height="30" fill="${nw}"/><rect x="-20" y="224" width="440" height="2" fill="${SH}" opacity=".1"/>`;
  let j2="";[[224,232,26],[232,244,32]].forEach(([a,b,sp],i)=>{j2+=`M-20 ${b} H420`;for(let x=-20+(i%2)*sp/2;x<420;x+=sp)j2+=`M${f1(x)} ${a} V${b}`});
  s+=`<path d="${j2}" stroke="${T("#B09E84")}" stroke-width=".9" opacity=".7"/>`;
