function mouthSvg(G,M,Q,dx=0){const y=G.mY,k=G.mw;
  const T=d=>d.replace(/(-?\d*\.?\d+) (-?\d*\.?\d+)/g,(_,a,b)=>{const X=+a*k+dx,Y=+b*k+y;return F(Q.rot(X,Y))+" "+F(Y)});
  const fillM=(d,extra="")=>`<path d="${T(d)}" fill="${MFILL}"/>${extra}<path d="${T(d)}" fill="none" stroke="${MINK}" stroke-width=".6" stroke-linejoin="round"/>`;
  const kx=Q.k(dx,y),LW=.95;
  switch(M.mouth){
   case "happy":return fillM("M-4.1 -.2 Q0 1.3 4.1 -.2 C3.7 3.6 1.9 4.8 0 4.8 C-1.9 4.8 -3.7 3.6 -4.1 -.2Z",`<path d="${T("M-2.9 .5 Q0 1.5 2.9 .5 Q0 2.2 -2.9 .5Z")}" fill="#FFF8F0" opacity=".9"/><path d="${T("M-2.2 3.9 Q0 2.5 2.2 3.9 Q1.2 4.55 0 4.55 Q-1.2 4.55 -2.2 3.9Z")}" fill="${TONG}"/>`)+line(T("M-4.6 -.8 Q-4.5 -.1 -4 .1 M4.6 -.8 Q4.5 -.1 4 .1"),MINK,.5,.45);
   case "laugh":return fillM("M-4.9 -.7 Q0 1.1 4.9 -.7 C4.5 4.6 2.2 6.2 0 6.2 C-2.2 6.2 -4.5 4.6 -4.9 -.7Z",`<path d="${T("M-3.2 .3 Q0 1.3 3.2 .3 Q0 1.9 -3.2 .3Z")}" fill="#FFF8F0" opacity=".85"/><path d="${T("M-2.9 5 Q0 3 2.9 5 Q1.6 5.9 0 5.9 Q-1.6 5.9 -2.9 5Z")}" fill="${TONG}"/>`)+line(T("M-5.4 -1.4 Q-5.3 -.5 -4.8 -.3 M5.4 -1.4 Q5.3 -.5 4.8 -.3"),MINK,.5,.45);
   case "sad":return line(T("M-2.7 2.6 Q0 .5 2.7 2.6"),MINK,LW)+line(T("M-1.1 3.6 Q0 4.1 1.1 3.6"),MINK,.5,.35);
   case "scared":return fillM("M-2 2.1 C-2 .9 -.8 .8 -.1 1.2 C.6 .8 2.2 .9 2.5 2.1 C2.7 3.4 1.5 3.9 .3 3.8 C-.9 4 -2.1 3.4 -2 2.1Z",`<path d="${T("M-1.1 3.4 Q.3 2.6 1.7 3.4 Q.3 3.9 -1.1 3.4Z")}" fill="${TONG}" opacity=".9"/>`);
   case "o":{const X=Q.rot(dx,y+2.2*k);return `<ellipse cx="${F(X)}" cy="${F(y+2.2*k)}" rx="${F(1.9*k*kx)}" ry="${F(2.4*k)}" fill="${MFILL}" stroke="${MINK}" stroke-width=".6"/><ellipse cx="${F(X)}" cy="${F(y+3.75*k)}" rx="${F(1.1*k*kx)}" ry="${F(.6*k)}" fill="${TONG}"/>`}
   case "angry":return line(T("M-2.3 2.5 Q0 1 2.3 2.5"),MINK,LW)+line(T("M-.8 3.3 Q0 3.7 .8 3.3"),MINK,.5,.35);
   case "calm":return line(T("M-2.8 .4 Q0 2.6 2.8 .4"),MINK,LW);
   case "calm2":return line(T("M-3.3 .1 Q0 2.9 3.3 .1"),MINK,LW)+line(T("M-3.7 -.4 Q-3.9 0 -3.6 .5 M3.7 -.4 Q3.9 0 3.6 .5"),MINK,.5,.45);
   case "sleep":{const X=Q.rot(dx+.4,y+1.6*k);return `<ellipse cx="${F(X)}" cy="${F(y+1.6*k)}" rx="${F(1.1*k*kx)}" ry="${F(.9*k)}" fill="${MFILL}" stroke="${MINK}" stroke-width=".6"/>`}
   case "side":return line(T("M.2 1.8 Q2 1 3.8 1.5"),MINK,LW)+line(T("M3.7 .9 Q4.3 1.4 4 2"),MINK,.55,.55);
   case "sorry":return line(T("M-2.8 2.2 Q-2 1.1 -1 1.7 Q0 2.3 1 1.5 Q2 .9 2.8 1.6"),MINK,LW);
   case "shy":return line(T("M-1 1 Q.6 2.3 2.2 1"),MINK,LW);
  }return ""}

