/* ---------- 2 kemikli ters kinematik ---------- */
function ik(S,T,L1,L2,bend){let dx=T[0]-S[0],dy=T[1]-S[1],d=Math.hypot(dx,dy);const mx=L1+L2-.05,mn=Math.abs(L1-L2)+.5;
  if(d>mx){dx*=mx/d;dy*=mx/d;d=mx}if(d<mn){dx*=mn/Math.max(d,.01);dy*=mn/Math.max(d,.01);d=mn}
  const a=Math.acos(clamp((L1*L1+d*d-L2*L2)/(2*L1*d),-1,1)),b=Math.atan2(dy,dx)+bend*a;
  const E=[S[0]+Math.cos(b)*L1,S[1]+Math.sin(b)*L1],W=[S[0]+dx,S[1]+dy];return {S,E,W,dir:Math.atan2(W[1]-E[1],W[0]-E[0])}}

