/* ---------- iskelet ---------- */
function config(o,preset){let pr=typeof preset==="string"?HUMAN.presets[preset]:preset;if(typeof pr==="function")pr=pr(o);pr=pr||{};const C={...pr,...o};
  if(typeof pr.fix==="function")pr.fix(C);C.type=TYPES[C.type]?C.type:"child";return C}
const DEF_TURN={walk:.7,run:.75,point:.45,hug:.45};
function turnOf(C){const pose=C.pose||"stand";let t=C.turn;if(t==null||isNaN(+t))t=(pose==="seat"&&(C.type==="adult"||C.type==="elder")&&!C.wheelchair)?.5:(DEF_TURN[pose]??.15);return clamp(+t,-1,1)}
function skel(C){const T=bodyT(C),G=faceGeo(C,T);const pose=C.pose||"stand",ad=C.type==="adult"||C.type==="elder";let mood=MOOD[C.mood]&&C.mood!=="hugjoy"?C.mood:"happy";
  if(ad&&pose==="hug"&&!C.hold&&(!C.mood||C.mood==="happy"))mood="hugjoy";
  const wc=!!C.wheelchair&&C.type!=="baby";const t=Math.abs(C._t??turnOf(C));
  let lp=pose;if(wc)lp="seat";else if(!["sit","seat","jump","run","crawl"].includes(pose))lp="stand";
  const seatY=-T.seat;let by=0;
  if(lp==="sit")by=T.sitDrop;else if(lp==="seat")by=(seatY-1)-T.hem;else if(lp==="jump")by=-T.H*.09;else if(lp==="run")by=-T.H*.02;
  const K={T,G,C,pose,lp,mood,by,wc,seatY,t,ad,footY:wc?-T.H*.085:(lp==="seat"?Math.min(0,seatY+T.legW*.35+(T.ank-T.hipY)*.5+T.H*.047):0)};
  const slump=MOOD[mood].slump&&pose!=="lie"?(ad?2.6:1.3):0;
  /* yaşlı duruşu: baş hafif öne-aşağı, yuvarlak omuz, üst gövde ~3.5° öne eğik (build'de döndürülür) */
  K.stoop=C.type==="elder"&&C.stoop!==false&&!wc&&lp==="stand"&&pose!=="lie"?1:0;
  K.shDrop=K.stoop*1.5+(ad?slump*.5:0)+((mood==="sad"||mood==="sorry")&&(lp==="stand"||lp==="seat")&&pose!=="lie"?(ad?2:1.3):0);
  K.hs=T.hs||1;K.hy=T.hy+by+slump*.8+K.stoop*1.8-G.chin*(K.hs-1)*.5+(mood==="sad"&&pose!=="lie"?(ad?1.6:1.1):0);
  /* ağırlık aktarımı (contrapposto): ayakta dururken gövde hafif yana, baş ters yöne eğilir; sağ bacak taşır, sol bacak gevşek */
  K.contra=pose==="stand"&&lp==="stand"&&!wc&&!K.stoop&&C.contra!==false&&t<.35&&!["shy","angry","sleep","scared"].includes(mood)?1:0;K.shY=T.shY+by+slump;K.hem=T.hem+by;K.hipY=T.hipY+by;
  K.fw=ad&&lp==="seat"&&!wc?T.H*(.05+.15*t):0;
  /* gövde dönüşü: uzak (yüz tarafı, x>0) yarı %30 daralır; göğüs öğeleri öne kayar */
  K.bm=(x,y)=>[x>0?x*(1-.3*t):x*(1-.05*t),y];
  K.bs=x=>K.bm(x,0)[0]+t*T.shW*.32*Math.max(0,1-(x/(T.shW+1))**2);
  K.hx=t*1.8;K.nx=t*1.2;
  const sj=T.shW-T.H*.01-K.shDrop*.5,sy=K.shY+T.H*.03+K.shDrop;K.sh=[[-sj*(1-.05*t),sy],[sj*(1-.3*t),sy]];
  K.chin=[K.hx+t*3,K.hy+G.chin*K.hs];
  return K}

/* kol planı (sağ kol R: x>0 = 3/4'te uzak kol) → {t:[x,y], bend, kind, layer:"split"|"back"|"front", cls, sw:{f,b,m}} */
function armPlan(K,hr){const {T,C,lp,wc,t}=K,pose=K.pose,L=T.L1+T.L2,[SL,SR]=K.sh,sy=SR[1];let mood=K.mood;const q=t>=.35;
  const lay=(sd,cross)=>q?(sd<0?"front":(cross?"split":"back")):"split";
  const rest=sd=>{const S=sd<0?SL:SR;return {t:[S[0]+sd*(1.4+T.H*.008),sy+L*.95],bend:-sd,kind:"fist",layer:lay(sd,0)}};
  const lap=sd=>K.fw?{t:[K.bs(sd*T.hipX*1.05)+K.fw*.62,K.seatY-T.legW*.95],bend:-sd,kind:"fist",layer:lay(sd,1)}:({t:[K.bs(sd*T.hipX*1.15)+(K.lp==="seat"?t*T.H*.05:0),K.seatY-T.H*.01],bend:-sd,kind:"fist",layer:lay(sd,1)});
  const P={};
  /* kucakta bebek/küçük karakter: bir kol altından destekler, diğeri üstünden sarar (ikisi de nesnenin önünde) */
  const cradle=()=>{P.L={t:[K.bs(T.shW*.42),sy+L*.8],bend:-1,kind:"fist",layer:"front",hdir:rad(10),handTop:1};P.R={t:[K.bs(T.shW*.62),sy+L*.46],bend:1,kind:"open",layer:"front",hdir:rad(170),handTop:1}};
  const base=sd=>wc||lp==="seat"?(sd<0&&wc&&C.rimHand?{...wheelHand(K,-1),bend:1,kind:"fist",layer:lay(sd,0)}:lap(sd)):lp==="sit"?{t:[sd*(T.hemW*1.4-2),K.hipY+2.6],bend:-sd,kind:"fist",layer:"split"}:rest(sd);
  P.L=base(-1);P.R=base(1);
  const both=f=>{P.L=f(-1);P.R=f(1)};
  const hc=[K.hx,K.hy],ext=hr.ext||{w:21,top:-24};
  /* kalkık el baş/saç hattından en az 4 birim uzak kalsın */
  const clear=(sd,a0,a1,rho)=>{const S=sd<0?SL:SR;const m=4+T.handR*1.5;let best=null;
    for(let a=a1;a>=a0;a-=3){const A=rad(a),x=S[0]+sd*Math.cos(A)*rho,y=S[1]-Math.sin(A)*rho;const dy=y-hc[1],ry=(dy<0?-ext.top:K.G.chin)+m,rx=(sd>0?(ext.wR||ext.w):(ext.wL||ext.w))+m;
      if(((x-hc[0])/rx)**2+(dy/ry)**2>=1){best=[x,y];break}}
    return best||[S[0]+sd*rho*.98,S[1]-rho*.12]};
  switch(pose){
   case "run":case "walk":{if(wc){both(sd=>({...wheelHand(K,sd),bend:sd,kind:"fist",layer:lay(sd,0)}));break}
     const run=pose==="run",du=run?".5s":".9s";
     if(q){if(run){P.R={E:[SR[0]+T.L1*.5,sy+T.L1*.84],t:[SR[0]+T.L1*.5+T.L2*.82,sy+T.L1*.84-T.L2*.5],bend:1,kind:"fist",layer:"back",sw:{f:0,b:40,m:20},du};
         P.L={E:[SL[0]-T.L1*.62,sy+T.L1*.76],t:[SL[0]-T.L1*.62+T.L2*.2,sy+T.L1*.76+T.L2*.96],bend:-1,kind:"fist",layer:"front",sw:{f:-40,b:0,m:-20},du}}
       else{P.R={t:[SR[0]+L*.34,sy+L*.64],bend:1,kind:"open",layer:"back",sw:{f:0,b:34,m:17},du,hdir:rad(-12)};P.L={t:[SL[0]-L*.36,sy+L*.84],bend:-1,kind:"open",layer:"front",sw:{f:-34,b:0,m:-17},du}}}
     else{if(run){P.R={E:[SR[0]+2,sy+T.L1*.9],t:[SR[0]-2,sy+L*.5],bend:-1,kind:"fist",layer:"front",sw:{f:0,b:10,m:5},du};P.L={t:[SL[0]-L*.5,sy+L*.72],bend:1,kind:"open",layer:"front",sw:{f:-10,b:0,m:-5},du}}
       else{P.R={t:[SR[0]-3.4,sy+L*.76],bend:-1,kind:"open",layer:"front",sw:{f:0,b:-7,m:-3},du};P.L={t:[SL[0]-3.4,sy+L*.86],bend:1,kind:"open",layer:"front",sw:{f:7,b:0,m:3},du}}}
     break}
   case "crawl":if(wc){P.R={t:[SR[0]+L*.92,sy+L*.42],bend:1,kind:"open",layer:"split"}}break;
   case "wave":{const ws=(ext.wR||ext.w)>(ext.wL||ext.w)+2?-1:1;K.waveSd=ws;const tg=clear(ws,12,82,L*.94);P[ws<0?"L":"R"]={t:tg,bend:ws,kind:"open",cls:"wave",layer:"split"};break}
   case "point":P.R={t:[SR[0]+L-.6,sy+1.4],bend:1,kind:"point",layer:"split"};break;
   case "hold":if(C._cradle){cradle();break}both(sd=>({t:[K.bs(sd*T.handR*1.5),sy+L*.66],bend:-sd,kind:"fist",layer:lay(sd,1)}));break;
   case "clap":both(sd=>({t:[K.bs(sd*T.handR*1.1),sy+L*.36],bend:-sd,kind:"open",layer:lay(sd,1),hdir:-Math.PI/2+sd*.28}));break;
   case "hug":if(C._cradle){cradle();break}
     if(K.ad&&!C.hold){/* sarılma: iki önkol içe ve birbirine doğru kıvrılır (kucaklanan gövdeyi sarar) */
       P.R={t:[SR[0]+L*.66,sy+L*.26],bend:1,kind:"open",layer:"split",hdir:rad(125)};P.L={t:[SR[0]+L*.5,sy+L*.58],bend:1,kind:"open",layer:"front",hdir:rad(-35)};break}
     if(C.hold){P.R={t:[K.bs(-T.shW*.46),sy+L*.44],bend:-1,kind:"fist",layer:"split"};P.L={t:[K.bs(T.shW*.5),sy+L*.58],bend:1,kind:"fist",layer:"front"}}
     else{P.R={t:[SR[0]+L*.86,sy+L*.2],bend:1,kind:"open",layer:"split"};P.L={t:[K.bs(T.shW*.6)+2,sy+L*.36],bend:1,kind:"open",layer:"front"}}break;
   case "open":both(sd=>({t:[(sd<0?SL:SR)[0]+sd*L*.88,sy-L*.14],bend:sd,kind:"open",layer:lay(sd,1)}));break;
   case "jump":both(sd=>{const tg=clear(sd,30,100,L*.94);return {t:tg,bend:sd,kind:"open",layer:lay(sd,1)}});break;
   case "lie":both(sd=>({t:[sd*4.6,sy+L*.86],bend:-sd,kind:"fist",layer:"front"}));break;
   case "stand":case "sit":case "seat":
    if(C.gesture===false||lp==="sit"||(C.hold&&pose==="stand"))break;
    {/* ruh haline göre beden dili (v4): her ifade kendi kol/el duruşunu taşır; o.hold varsa kollar ona bırakılır */
     const G=K.G,hs=K.hs,st=lp==="stand"&&!wc,eyeR=[K.hx+G.dx*hs*(1-.25*t),K.hy+G.eyY*hs];
     const cheekR=[K.hx+G.blX*hs*.95*(1-.2*t),K.hy+G.blY*hs+T.handR*1.3];
     if(mood==="think")P.R={t:[K.chin[0]+3.4,K.chin[1]+T.handR*.2],bend:-1,kind:"fist",layer:"split",chin:1};
     else if(mood==="happy"&&st)P.R={t:[SR[0]+L*.46,sy+L*.74],bend:1,kind:"open",layer:lay(1,0),hdir:rad(52)};
     else if(mood==="laugh")both(sd=>({t:[K.bs(sd*T.waW*.5),T.waY+K.by+T.H*.025],bend:-sd,kind:"open",layer:lay(sd,1),hdir:sd<0?rad(-8):rad(188)}));
     else if(mood==="sad"||mood==="calm")both(sd=>({t:[K.bs(sd*T.handR*.45),sy+L*(mood==="sad"?.9:.78)],bend:-sd,kind:"fist",layer:lay(sd,1),hdir:rad(90+sd*28)}));
     else if(mood==="scared")both(sd=>({t:[K.chin[0]+sd*T.handR*1.45,K.chin[1]+T.handR*.9],bend:-sd,kind:"fist",layer:"split"}));
     else if(mood==="surprised")both(sd=>({t:[(sd<0?SL:SR)[0]+sd*L*.5,sy+L*.02],bend:sd,kind:"open",layer:lay(sd,1)}));
     else if(mood==="angry"&&!wc&&lp!=="seat")both(sd=>({t:[K.bs(sd*(T.waW+.6)),T.waY+K.by+T.H*.03],bend:-sd,kind:"fist",layer:lay(sd,1),hdir:rad(90-sd*70)}));
     else if(mood==="sorry"&&!wc&&lp!=="seat")both(sd=>({t:[sd*2,sy+L*.72],E:[(sd<0?SL:SR)[0]+sd*(T.waW*.2+T.H*.018),sy+T.L1*.9],bend:-sd,kind:"hide",layer:"back"}));
     else if(mood==="sorry")both(sd=>({t:[K.bs(sd*T.handR*.35),sy+L*.84],bend:-sd,kind:"fist",layer:lay(sd,1)}));
     else if(mood==="shy"){P.R={t:cheekR,bend:-1,kind:"open",layer:"split",hdir:rad(-100)};if(!wc&&lp!=="seat")P.L={t:[K.bs(-T.handR*.1),sy+L*.8],bend:1,kind:"fist",layer:lay(-1,1)}}
     else if(mood==="sleep")P.R={t:[eyeR[0]+T.handR*.7,eyeR[1]+T.handR*.9],bend:-1,kind:"fist",layer:"split",hdir:rad(-120)};}
  }
  /* baston: sol el biraz dışarıda ve önde, bastonun sapını kavrar */
  if(C.cane&&!wc&&(pose==="stand"||pose==="walk")&&P.L&&!P.L.cls&&(P.L.kind==="fist"||P.L.kind==="open")&&P.L.t[1]>sy+L*.6)P.L={t:[SL[0]-T.H*.06,sy+L*.82],bend:1,kind:"fist",layer:lay(-1,0),cane:1};
  return P}

/* ---------- kol çizimi ---------- */
function armSvg(A,sd,K,S,top){const {T,C}=K;const Sh=K.sh[sd<0?0:1],S0=A.layer==="front"&&top.sleeve!=="puff"?[Sh[0]-sd*T.sleeveW*.34,Sh[1]+T.sleeveW*.12]:Sh;const t=[A.t[0],A.t[1]];
  let R;if(A.E){const E=[A.E[0],A.E[1]],dx=t[0]-E[0],dy=t[1]-E[1],dl=Math.hypot(dx,dy)||1;R={S:S0,E,W:[E[0]+dx/dl*T.L2,E[1]+dy/dl*T.L2],dir:Math.atan2(dy,dx)}}else R=ik(S0,t,T.L1,T.L2,A.bend);const {E,W}=R;
  const sleeve=top.sleeve,cl=top.sc||top.c;let up="",lo="",cap="";
  const aw=T.armW,sw=T.sleeveW;
  const stripes=(dpath,a,b,w)=>{if(!top.stripeC)return "";const id=uid("ss"),h=top.stripeH;let s="";const L=Math.hypot(b[0]-a[0],b[1]-a[1]),n=Math.max(1,Math.floor(L/h));
    const [ux,uy]=nrm(b[0]-a[0],b[1]-a[1]);for(let i=0;i<=n;i++){const c=lerp(a,b,(i+.5)/(n+.5));s+=line(`M${F(c[0]+uy*w)} ${F(c[1]-ux*w)} L${F(c[0]-uy*w)} ${F(c[1]+ux*w)}`,top.stripeC,h/2)}
    return `<clipPath id="${id}"><path d="${dpath}"/></clipPath><g clip-path="url(#${id})">${s}</g><path d="${dpath}" fill="none" stroke="${cl.l}" stroke-width="1"/>`};
  const skinC={...S,h:S.rim};
  /* yumuşak kavisli kol: üst kol ve ön kol ortası bükülme yönüne hafif şişer (düz çubuk değil) */
  const mid=lerp(S0,W,.5),ed=Math.hypot(E[0]-mid[0],E[1]-mid[1]);let [ox,oy]=ed>.3?nrm(E[0]-mid[0],E[1]-mid[1]):[0,0];
  const bowP=(a,b,k,w)=>{const m=lerp(a,b,.5);return [m[0]+ox*w*k,m[1]+oy*w*k]};
  const [tx,ty]=nrm(W[0]-S0[0],W[1]-S0[1]);
  /* dirsek kıvrımı: bükülmenin iç tarafında iki kısa kumaş katlanması */
  const crease=(w,c)=>{if(ed<T.L1*.14)return "";const ix=-ox,iy=-oy,P0=[E[0]+ix*w*.08,E[1]+iy*w*.08];
    return line(`M${F(P0[0]+tx*w*.18)} ${F(P0[1]+ty*w*.18)} Q${F(E[0]+ix*w*.3)} ${F(E[1]+iy*w*.3)} ${F(E[0]+ix*w*.46-tx*w*.22)} ${F(E[1]+iy*w*.46-ty*w*.22)} M${F(P0[0]+tx*w*.5)} ${F(P0[1]+ty*w*.5)} Q${F(E[0]+ix*w*.26+tx*w*.3)} ${F(E[1]+iy*w*.26+ty*w*.3)} ${F(E[0]+ix*w*.4+tx*w*.1)} ${F(E[1]+iy*w*.4+ty*w*.1)}`,c,.7,.6)};
  if(sleeve==="long"){const pts=[S0,bowP(S0,E,.1,sw),E,bowP(E,W,.06,sw),W],ws=[sw*1.04,sw*1.03,sw*.95,sw*.97,sw*.9];const whole=limb(pts,ws,cl)+stripes(limbD(pts,ws),S0,W,sw)+crease(sw,cl.l);
    let cuff;if(C.rib&&!C.coat){/* örgü manşet: koyu bant + kola paralel kaburga çizgileri */
      const a=lerp(W,E,.02),b=lerp(W,E,.26),[ux,uy]=nrm(b[0]-a[0],b[1]-a[1]),cc=cloth(mix(cl.b,cl.d,.45));cuff=limb([a,b],[sw*.98,sw*.98],cc,{rim:false});
      cuff+=line([-.33,-.11,.11,.33].map(k=>`M${F(a[0]-uy*sw*k+ux*.6)} ${F(a[1]+ux*sw*k+uy*.6)} L${F(b[0]-uy*sw*k-ux*.4)} ${F(b[1]+ux*sw*k-uy*.4)}`).join(" "),cl.l,.55,.5)}
    else cuff=limb([lerp(W,E,.02),lerp(W,E,.22)],[sw*.98,sw*.98],top.cuff||cl,{rim:false});
    up=whole+cuff}
  else{const m=lerp(S0,E,.25);up=limb([m,bowP(m,E,.1,aw),E,bowP(E,W,.08,aw),W],[aw*1.06,aw*1.05,aw*.9,aw*.93,aw*.78],skinC,{rimC:S.rim,rimOp:S.dark?.65:.4});
    if(sleeve==="short"){const e=lerp(S0,E,.62),pts=[S0,e],ws=[sw*1.1,sw*1.02];
      up+=limb(pts,ws,cl,{rim:false})+stripes(limbD(pts,ws),S0,e,sw);const a=Math.atan2(e[1]-S0[1],e[0]-S0[0]),nx=-Math.sin(a),ny=Math.cos(a),hw=sw*.5;
      up+=line(`M${F(e[0]-nx*hw)} ${F(e[1]-ny*hw)} L${F(e[0]+nx*hw)} ${F(e[1]+ny*hw)}`,cl.l,.8,.5)}
    else if(sleeve==="puff"){/* küçük büzgülü kabarık kol: desen kola taşınır, 3 büzgü çizgisi + üst parlama */
      const c=lerp(S0,E,.2),a=Math.atan2(E[1]-S0[1],E[0]-S0[0]),dg=a*180/Math.PI,rx=sw*.46,ry=sw*.4,id=uid("pf");
      const shp=`<ellipse cx="0" cy="0" rx="${F(rx)}" ry="${F(ry)}"/>`;
      cap=`<g transform="translate(${F(c[0])} ${F(c[1])}) rotate(${F(dg)})"><clipPath id="${id}">${shp}</clipPath><ellipse rx="${F(rx)}" ry="${F(ry)}" fill="${top.base}" stroke="${cl.l}" stroke-width="1"/><g clip-path="url(#${id})"><ellipse cx="${F(rx*.35)}" cy="${F(ry*.45)}" rx="${F(rx*.8)}" ry="${F(ry*.7)}" fill="${cl.d}" opacity=".45" filter="${u("soft2")}"/>${line(`M${F(rx*.95)} ${F(-ry*.9)} Q${F(rx*.2)} 0 ${F(rx*.95)} ${F(ry*.9)} M${F(rx*.95)} ${F(-ry*.35)} Q${F(rx*.1)} ${F(ry*.1)} ${F(rx*.95)} ${F(ry*.4)} M${F(rx*.3)} ${F(-ry*1.1)} Q${F(-rx*.3)} ${F(-ry*.1)} ${F(rx*.2)} ${F(ry*1.1)}`,cl.d,.7,.7)}<ellipse cx="${F(-rx*.25)}" cy="${F(-ry*.45)}" rx="${F(rx*.45)}" ry="${F(ry*.22)}" fill="#fff" opacity=".45" filter="${u("soft2")}"/></g>${line(`M${F(rx*.92)} ${F(-ry*.75)} Q${F(rx*1.12)} 0 ${F(rx*.92)} ${F(ry*.75)}`,cl.l,1.5,.9)}${line(`M${F(rx*.9)} ${F(-ry*.7)} Q${F(rx*1.08)} 0 ${F(rx*.9)} ${F(ry*.7)}`,lt(cl.b,.3),.7,.8)}</g>`}}
  const hd=A.hdir??R.dir;let hand=A.kind!=="hide"?handSvg(W[0]+Math.cos(R.dir)*T.handR*.5,W[1]+Math.sin(R.dir)*T.handR*.5,T.handR,S,A.kind,hd,sd):"";
  const layer=A.layer||"split";let back="",front="";
  let handOut="";if(A.handTop){handOut=hand;hand=""}
  if(layer==="back")back=up+hand;else if(layer==="front")front=up+cap+hand,cap="";else{back=up;front=hand}
  /* sallanma grupları */
  if(A.cls==="wave"){const xs=[Sh[0],E[0],W[0]],ys=[Sh[1],E[1],W[1]],mnx=Math.min(...xs)-6,mxx=Math.max(...xs)+6,mny=Math.min(...ys)-7,mxy=Math.max(...ys)+5;
    const Wd=Math.max((S0[0]-mnx)/.2,(mxx-S0[0])/.8),Hd=Math.max((S0[1]-mny)/.9,(mxy-S0[1])/.1);const bx=[S0[0]-.2*Wd,S0[1]-.9*Hd,Wd,Hd];
    const wrap=x=>x?`<g class="wave"><rect x="${F(bx[0])}" y="${F(bx[1])}" width="${F(bx[2])}" height="${F(bx[3])}" fill="none"/>${x}</g>`:"";back=wrap(back);front=wrap(front);cap=wrap(cap)}
  if(A.sw){const xs=[S0[0],E[0],W[0]],ys=[E[1],W[1]];const hw=Math.max(...xs.map(x=>Math.abs(x-S0[0])))+T.handR*2.2,hh=Math.max(...ys)-S0[1]+T.handR*2.4;
    const wrap=x=>x?`<g class="lg harm LGX" style="--f:${A.sw.f}deg;--b:${A.sw.b}deg;--m:${A.sw.m}deg;--du:${A.du||".9s"}"><rect x="${F(S0[0]-hw)}" y="${F(S0[1])}" width="${F(hw*2)}" height="${F(hh)}" fill="none"/>${x}</g>`:"";
    back=wrap(back);front=wrap(front)}
  return {back,front,cap,W,E,hand:handOut}}

/* ---------- bacaklar ---------- */
/* çoklu doğru üzerinde örnekleme: prof=[[t,genişlik çarpanı],...] → yumuşak baldır/diz profili */
function resamp(pts,prof){const L=[0];for(let i=1;i<pts.length;i++)L.push(L[i-1]+Math.hypot(pts[i][0]-pts[i-1][0],pts[i][1]-pts[i-1][1]));const tot=L[L.length-1]||1;
  const at=t=>{const d=t*tot;let i=1;while(i<L.length-1&&L[i]<d)i++;const seg=(L[i]-L[i-1])||1;return lerp(pts[i-1],pts[i],clamp((d-L[i-1])/seg,0,1))};
  return {p:prof.map(([t])=>at(t)),w:prof.map(([,w])=>w),at}}
const LEGP={skin:[[0,1.1],[.24,1.04],[.47,.84],[.6,.92],[.8,.8],[1,.7]],shin:[[0,.9],[.28,.96],[.7,.78],[1,.7]],pants:[[0,1.06],[.5,.98],[1,.92]],pshin:[[0,1],[1,.92]]};
function legDraw(K,S,bot,sd,pts,o={}){const {T,C}=K;const sock=C.socks?cloth(C.socks):null,shoe=cloth(C.shoes||"#5B4B7A");
  const A=pts[0],Z=pts[pts.length-1],c0=pts[pts.length-2];let s="";const legC=o.legs||bot.legs;
  if(legC==="pants"){const R=resamp(pts,o.shin?LEGP.pshin:LEGP.pants),ws=R.w.map(w=>w*T.legW);s+=limb(R.p,ws,bot.c);const Lz=Math.hypot(Z[0]-c0[0],Z[1]-c0[1]);
    s+=limb([lerp(Z,c0,.02),lerp(Z,c0,Math.min(.4,3/Lz))],[T.legW*.94,T.legW*.94],bot.cuff||bot.c,{rim:false,drop:false});
    /* kumaş: diz kıvrımı + paça kırılması */
    const [ux,uy]=nrm(Z[0]-A[0],Z[1]-A[1]),w=T.legW,kn=R.at(o.shin?.1:.5),an=R.at(.86);
    s+=line(`M${F(kn[0]-uy*w*.1-ux*w*.1)} ${F(kn[1]+ux*w*.1-uy*w*.1)} q${F(-uy*w*.18+ux*w*.12)} ${F(ux*w*.18+uy*w*.12)} ${F(-uy*w*.34+ux*w*.02)} ${F(ux*w*.34+uy*w*.02)}`,bot.c.l,.6,.45)
      +line(`M${F(an[0]+uy*w*.36)} ${F(an[1]-ux*w*.36)} q${F(-uy*w*.3+ux*w*.16)} ${F(ux*w*.3+uy*w*.16)} ${F(-uy*w*.62)} ${F(ux*w*.62)}`,bot.c.l,.6,.4)}
  else{const sk=C.tights?cloth(C.tights):{...S,h:S.rim};const R=resamp(pts,o.shin?LEGP.shin:LEGP.skin);s+=limb(R.p,R.w.map(w=>w*T.skinLegW),sk,{rimOp:S.dark?.55:.35});
    /* diz kapağı ipucu */
    if(!o.shin&&legC!=="shorts"){const kn=R.at(.48),[ux,uy]=nrm(Z[0]-A[0],Z[1]-A[1]),w=T.skinLegW;s+=line(`M${F(kn[0]-uy*w*.18)} ${F(kn[1]+ux*w*.18)} q${F(uy*w*.18+ux*w*.12)} ${F(-ux*w*.18+uy*w*.12)} ${F(uy*w*.36)} ${F(-ux*w*.36)}`,sk.l||S.l,.55,.35)}
    if(sock){const L=Math.hypot(Z[0]-c0[0],Z[1]-c0[1]),q=lerp(Z,c0,Math.min(.6,T.H*.05/L));s+=limb([Z,q],[T.skinLegW*.8,T.skinLegW*.8],sock,{rim:false,drop:false})+line(`M${F(q[0]-T.skinLegW*.42)} ${F(q[1])} h${F(T.skinLegW*.84)}`,sock.d,.8,.8)}
    if(legC==="shorts"){const k=lerp(A,pts[1],o.shortK??.58);s+=limb([A,k],[T.legW*1.14,T.legW*1.1],bot.c,{rim:false});
      const [ux,uy]=nrm(k[0]-A[0],k[1]-A[1]);s+=line(`M${F(k[0]-uy*T.legW*.5)} ${F(k[1]+ux*T.legW*.5)} L${F(k[0]+uy*T.legW*.5)} ${F(k[1]-ux*T.legW*.5)}`,bot.c.l,.7,.5)}}
  if(o.shoe!==false)s+=shoeSvg(Z[0]+(o.sx||0),Z[1]+T.H*.047+(o.sy||0),o.dir??sd,shoe,T,o.rot||0,C.sneaker,o.flipY||1);
  return s}
/* bebek ayağı: tabanı izleyiciye dönük küçük patik/çıplak ayak (taban yastığı + parmaklar) */
function babyFoot(x,y,sd,C,S,rot=0){const sc=C.socks?cloth(C.socks):null,b=sc?sc.b:S.b,l=sc?sc.l:S.l,pad=sc?mix(sc.b,"#F4B8B0",.5):mix(S.b,"#F08A8A",.3);
  return `<g transform="translate(${F(x)} ${F(y)}) rotate(${F(-sd*12+rot)})"><path d="M0 -4.6 C2.8 -4.6 3.6 -2 3.3 .6 C3 3.4 1.8 4.6 0 4.6 C-1.8 4.6 -3 3.4 -3.3 .6 C-3.6 -2 -2.8 -4.6 0 -4.6Z" fill="${b}" stroke="${l}" stroke-width=".8"/>`
   +`<ellipse cx="0" cy="1.2" rx="2" ry="2.6" fill="${pad}" opacity=".85"/><ellipse cx="0" cy="-2.2" rx="1.5" ry=".9" fill="${pad}" opacity=".7"/>`
   +[[-1.9,-4.1,.75],[-.6,-4.7,.8],[.8,-4.6,.72],[2,-3.9,.62]].map(([a,c,r])=>`<circle cx="${a}" cy="${c}" r="${r}" fill="${b}" stroke="${l}" stroke-width=".45"/>`).join("")+`</g>`}
/* her bacak kendi .lg grubunda; dönme noktası kalça (fill-box 50% 0) */
function lgWrap(s,hip,pts,vars,extra=0){const hw=Math.max(...pts.map(p=>Math.abs(p[0]-hip[0])))+9+extra,hh=Math.max(...pts.map(p=>p[1]))-hip[1]+6;
  return `<g class="lg hlg LGX" style="${vars}"><rect x="${F(hip[0]-hw)}" y="${F(hip[1])}" width="${F(hw*2)}" height="${F(hh)}" fill="none"/>${s}</g>`}
function legsSvg(K,S,bot){const {T,C,lp,t}=K;const hy=K.hipY,out=[];const q=t>=.35;
  const hipOf=sd=>[sd<0?-T.hipX*(1-.05*t):T.hipX*(1-.5*t),hy];
  if(lp==="sit"){/* bağdaş: dizler kalçanın ~1.4 katı dışarıda, baldırlar önde çapraz, her ayak karşı dizin altında */
    const kx=T.hemW*1.4,ky=hy+T.H*.024,dress=bot.legs==="skin"&&C.dress,skirt=bot.bt==="skirt";const L={},legsC=bot.legs;
    for(const sd of [-1,1]){const h=[sd*T.hipX*1.15,hy+1],k=[sd*kx,ky],a=[-sd*kx*.56,-T.H*.034];L[sd]={h,k,a}}
    const legC=(sd,pts,part)=>{if(legsC==="pants"){const ws=part==="thigh"?[T.legW*1.08,T.legW]:[T.legW*.98,T.legW*.86];let s=limb(pts,ws,bot.c);if(part==="shin"){const Z=pts[1],c0=pts[0];s+=limb([lerp(Z,c0,.02),lerp(Z,c0,.2)],[T.legW*.9,T.legW*.9],bot.cuff||bot.c,{rim:false})}return s}
      const sk=C.tights?cloth(C.tights):{...S,h:S.rim};const ws=part==="thigh"?[T.skinLegW*1.1,T.skinLegW*1.02]:[T.skinLegW*1.02,T.skinLegW*.84];let s=limb(pts,ws,sk,{rimOp:S.dark?.55:.35});
      if(part==="thigh"&&legsC==="shorts")s+=limb([pts[0],lerp(pts[0],pts[1],.62)],[T.legW*1.16,T.legW*1.1],bot.c,{rim:false});
      if(part==="shin"&&C.socks){const sock=cloth(C.socks),Z=pts[1];s+=limb([Z,lerp(Z,pts[0],.15)],[T.skinLegW*.9,T.skinLegW*.9],sock,{rim:false})}
      if(part==="thigh")s+=`<ellipse cx="${F(pts[1][0]-Math.sign(pts[1][0])*1.2)}" cy="${F(pts[1][1]-1.6)}" rx="1.6" ry=".9" fill="#fff" opacity=".35"/>`
      return s};
    const thigh=sd=>{const {h,k}=L[sd];return legC(sd,[h,k],"thigh")},shin=sd=>{const {k,a}=L[sd];return legC(sd,[k,a],"shin")};
    const shoe=cloth(C.shoes||"#5B4B7A");const foot=sd=>{const a=L[sd].a;return C.type==="baby"?babyFoot(a[0]-sd*1.4,-3.2,sd,C,S):shoeSvg(a[0]-sd*1.6,-.2,-sd,shoe,T,-6,C.sneaker)};
    if(dress){for(const sd of [-1,1])out.push(shoeSvg(sd*(kx-1.2),-.4,sd,shoe,T,-4,C.sneaker));return out.join("")}
    out.push(thigh(1),thigh(-1));
    const sh=foot(1)+shin(1)+foot(-1)+shin(-1);if(skirt)out.push(sh);else K.sitShins=sh;
    return out.join("")}
  if(lp==="seat"&&K.fw){/* yetişkin oturuş: uyluk öne (3/4'te yatay), diz ~90°, baldır dik, ayak yerde */
    for(const sd of (q?[1,-1]:[-1,1])){const far=q&&sd>0,h=hipOf(sd),k=[h[0]+sd*T.hipX*.25+K.fw-(far?1.4:0),Math.min(hy,K.seatY-T.legW*.42)-(far?1.4:0)],a=[k[0]+1.4*t,T.ank-(far?1.6:0)];
      let s="";const pts=[h,k],ws=bot.legs==="pants"||bot.legs==="shorts"?[T.legW*1.16,T.legW*1.08]:[T.skinLegW*1.2,T.skinLegW*1.1];
      if(bot.legs==="pants"||bot.legs==="shorts")s+=limb(pts,ws,bot.c,{rim:false});else s+=limb(pts,ws,C.tights?cloth(C.tights):{...S,h:S.rim});
      s+=legDraw(K,S,bot,sd,[k,a],{dir:q?1:sd,shortK:0,shin:1,legs:bot.legs==="shorts"?"skin":bot.legs});
      s+=`<ellipse cx="${F(k[0]+ws[1]*.12)}" cy="${F(k[1]-ws[1]*.18)}" rx="${F(ws[1]*.26)}" ry="${F(ws[1]*.16)}" fill="#fff" opacity=".22"/>`;
      out.push(far?`<g opacity=".96">${s}</g>`:s)}
    return out.join("")}
  if(lp==="seat"){const fy=K.footY;
    for(const sd of (q?[1,-1]:[-1,1])){const h=hipOf(sd),fw=t*T.H*.1,k=[h[0]+sd*.6*(1-t)+fw,K.seatY+T.legW*.35-(q&&sd>0?1:0)],a=[k[0]+sd*.3*(1-t)+t*1.2,fy-T.H*.047-(q&&sd>0?1.2:0)];
      let s="";const pts=[h,k];
      if(bot.legs==="pants"||bot.legs==="shorts")s+=limb(pts,[T.legW*1.28,T.legW*1.18],bot.c,{rim:false});else s+=limb(pts,[T.skinLegW*1.3,T.skinLegW*1.2],C.tights?cloth(C.tights):{...S,h:S.rim});
      s+=legDraw(K,S,bot,sd,[k,a],{dir:q?1:sd,shortK:0,shin:1,legs:bot.legs==="shorts"?"skin":bot.legs});out.push(s)}
    return out.join("")}
  if(lp==="jump"){for(const sd of (q?[1,-1]:[-1,1])){const h=hipOf(sd),pts=[h,[h[0]+sd*T.H*.06,hy+T.H*.12],[h[0]+sd*T.H*.015,hy+T.H*.2]];out.push(lgWrap(legDraw(K,S,bot,sd,pts,{rot:20,dir:q?1:sd}),h,pts,"--f:-10deg;--b:10deg;--km:.9"))}return out.join("")}
  const walk=K.pose==="walk",run=lp==="run",shy=(K.mood==="shy"||K.mood==="scared")&&K.pose==="stand"&&C.gesture!==false;const legLen=K.T.ank-hy;
  const straight=(h,ang,dx=0)=>{const a=rad(ang),Lh=legLen;return [h,[h[0]-Math.sin(a)*Lh*.5+dx*.5,h[1]+Math.cos(a)*Lh*.5],[h[0]-Math.sin(a)*Lh+dx,h[1]+Math.cos(a)*Lh]]};
  const order=q||K.C.pose==="lie"?[1,-1]:[-1,1];
  for(const sd of order){const h=hipOf(sd);let pts,o={dir:q?1:sd},vars;
    if(run&&q){if(sd<0){const k=[h[0]+T.H*.075,h[1]+T.H*.07];pts=[h,k,[k[0]+T.H*.012,k[1]+T.H*.105]];o.rot=-6;vars="--f:0deg;--b:34deg;--m:17deg;--km:.9;--du:.5s"}
      else{const k=[h[0]-T.H*.04,h[1]+T.H*.11];pts=[h,k,[k[0]-T.H*.1,k[1]+T.H*.04]];o.rot=55;vars="--f:-34deg;--b:0deg;--m:-17deg;--km:.9;--du:.5s"}}
    else if(run){if(sd<0){pts=[h,[h[0]-T.H*.01,hy+T.H*.085],[h[0]-T.H*.035,hy+T.H*.175]];o.rot=14}else{pts=[h,[h[0]+T.H*.035,hy+T.H*.13],[h[0]+T.H*.06,T.ank]];o.rot=-8}vars=`--kf:1;--kb:1;--km:.86;--du:.5s`}
    else if(walk&&q){if(sd<0){pts=straight(h,-19);o.rot=-10;vars="--f:0deg;--b:34deg;--m:17deg;--km:.88"}
      else{const a=rad(15),Lh=legLen,k=[h[0]-Math.sin(a)*Lh*.5,h[1]+Math.cos(a)*Lh*.5];pts=[h,k,[k[0]-Math.sin(rad(30))*Lh*.5,k[1]+Math.cos(rad(30))*Lh*.5]];o.rot=22;vars="--f:-34deg;--b:0deg;--m:-17deg;--km:.88"}}
    else if(walk){if(sd<0){pts=[h,[h[0]-1.2,h[1]+legLen*.44],[h[0]+.2,T.ank-T.H*.055]];o.rot=-4;vars="--kf:1;--kb:1.14;--km:1.14"}else{pts=[h,[h[0]+T.H*.013,T.ank]];vars="--kf:.87;--kb:1;--km:1"}}
    else if(q){pts=[h,[h[0]+(sd<0?1.2:.6)*t,T.ank-(sd>0?1.4*t:0)]];vars="--f:-12deg;--b:12deg;--m:0deg;--km:.88";o.rot=sd>0?-3:0}
    else if(K.C.pose==="lie"){const lx=-(T.hemW-T.legW*.56)+(sd>0?2.2:0),h2=[lx,hy],a=[lx+(sd>0?.6:0),T.ank];pts=[h2,a];o.dir=1;o.rot=0;vars="--km:.86";
      out.push(lgWrap(legDraw(K,S,bot,sd,pts,o),h2,pts,vars));continue}
    else if(K.contra){if(sd>0)pts=[h,[h[0]+.4,T.ank]];else pts=[h,[h[0]-.3,(hy+T.ank)/2+.4],[h[0]-T.H*.03,T.ank-T.H*.005]];o.rot=sd>0?-4:-9;vars="--km:.86"}
    else{const a=[sd*(T.hipX+(sd>0?T.H*.013:.2)),T.ank];pts=shy?[h,[sd*(T.hipX-1.6),(hy+T.ank)/2],[sd*(T.hipX+.6),T.ank]]:[h,a];o.rot=shy&&sd>0?-14:(sd>0?-5:0);if(K.C.pose==="lie"){o.dir=1;o.rot=0}vars="--km:.86"}
    out.push(lgWrap(legDraw(K,S,bot,sd,pts,o),h,pts,vars))}
  return out.join("")}

/* ---------- gövde / kıyafet ---------- */
function torsoD(K,flare=0,hemY){const T=K.T,nw=T.nw,sy=K.shY,dr=K.shDrop||0,sw=T.shW-dr*.4,wy=T.waY+K.by,ww=T.waW,hy=hemY??K.hem,hw=T.hemW+flare;
  return `M${F(-nw)} ${F(sy-2.4)} C${F(-nw-2.6-dr)} ${F(sy-2+dr*.3)} ${F(-sw+1.6)} ${F(sy-1.6+dr*.8)} ${F(-sw)} ${F(sy+1.6+dr)} C${F(-sw-1)} ${F(sy+4.4+dr)} ${F(-ww)} ${F(wy-5)} ${F(-ww)} ${F(wy)} C${F(-ww)} ${F(wy+4)} ${F(-hw)} ${F(hy-4)} ${F(-hw)} ${F(hy)} Q0 ${F(hy+2.4)} ${F(hw)} ${F(hy)} C${F(hw)} ${F(hy-4)} ${F(ww)} ${F(wy+4)} ${F(ww)} ${F(wy)} C${F(ww)} ${F(wy-5)} ${F(sw+1)} ${F(sy+4.4+dr)} ${F(sw)} ${F(sy+1.6+dr)} C${F(sw-1.6)} ${F(sy-1.6+dr*.8)} ${F(nw+2.6+dr)} ${F(sy-2+dr*.3)} ${F(nw)} ${F(sy-2.4)} Q0 ${F(sy+1.6)} ${F(-nw)} ${F(sy-2.4)}Z`}
function hemPath(xs,y,dy=2.6){let s="";for(let i=1;i<xs.length;i++)s+=`Q${F((xs[i]+xs[i-1])/2)} ${F(y+dy)} ${F(xs[i])} ${F(y)} `;return s}
function dressD(K,hemY,dw){const T=K.T,nw=T.nw,sy=K.shY,sw=T.shW,wy=T.waY+K.by,ww=T.waW-.6;const xs=[];for(let i=6;i>=0;i--)xs.push(-dw+2*dw*i/6);
  return `M${F(-nw)} ${F(sy-2.4)} C${F(-nw-2.6)} ${F(sy-2)} ${F(-sw+1.6)} ${F(sy-1.6)} ${F(-sw)} ${F(sy+1.6)} C${F(-sw-1)} ${F(sy+4.4)} ${F(-ww)} ${F(wy-5)} ${F(-ww)} ${F(wy)} C${F(-ww-1)} ${F(wy+6)} ${F(-dw+1.6)} ${F(hemY-8)} ${F(-dw)} ${F(hemY)} ${hemPath(xs.slice().reverse(),hemY)} C${F(dw-1.6)} ${F(hemY-8)} ${F(ww+1)} ${F(wy+6)} ${F(ww)} ${F(wy)} C${F(ww)} ${F(wy-5)} ${F(sw+1)} ${F(sy+4.4)} ${F(sw)} ${F(sy+1.6)} C${F(sw-1.6)} ${F(sy-1.6)} ${F(nw+2.6)} ${F(sy-2)} ${F(nw)} ${F(sy-2.4)} Q0 ${F(sy+1.6)} ${F(-nw)} ${F(sy-2.4)}Z`}
/* bağdaşta elbise: etek dizlerin üstünden dökülür */
function dressSitD(K,kx){const T=K.T,nw=T.nw,sy=K.shY,sw=T.shW,wy=T.waY+K.by,ww=T.waW-.6,hy=-T.H*.018;
  const side=sd=>`C${F(sd*(ww+1.4))} ${F(wy+5)} ${F(sd*(kx-2))} ${F(hy-9)} ${F(sd*(kx+1.2))} ${F(hy-6.2)} C${F(sd*(kx+3.4))} ${F(hy-4.6)} ${F(sd*(kx+2.6))} ${F(hy-.6)} ${F(sd*(kx+.6))} ${F(hy)}`;
  return `M${F(-nw)} ${F(sy-2.4)} C${F(-nw-2.6)} ${F(sy-2)} ${F(-sw+1.6)} ${F(sy-1.6)} ${F(-sw)} ${F(sy+1.6)} C${F(-sw-1)} ${F(sy+4.4)} ${F(-ww)} ${F(wy-5)} ${F(-ww)} ${F(wy)} ${side(-1)} Q${F(-kx*.5)} ${F(hy+2.2)} 0 ${F(hy+.6)} Q${F(kx*.5)} ${F(hy+2.2)} ${F(kx+.6)} ${F(hy)} C${F(kx+2.6)} ${F(hy-.6)} ${F(kx+3.4)} ${F(hy-4.6)} ${F(kx+1.2)} ${F(hy-6.2)} C${F(kx-2)} ${F(hy-9)} ${F(ww+1.4)} ${F(wy+5)} ${F(ww)} ${F(wy)} C${F(ww)} ${F(wy-5)} ${F(sw+1)} ${F(sy+4.4)} ${F(sw)} ${F(sy+1.6)} C${F(sw-1.6)} ${F(sy-1.6)} ${F(nw+2.6)} ${F(sy-2)} ${F(nw)} ${F(sy-2.4)} Q0 ${F(sy+1.6)} ${F(-nw)} ${F(sy-2.4)}Z`}

function topInfo(C){const tt=C.dress?"dress":(C.topType||"tee");const c=cloth(C.dress||C.top||"#4F8FD8");
  const sleeve={tee:"short",dress:C.sleeve||"puff",long:"long",hoodie:"long",shirt:"long",sweater:"long",cardigan:"long",vest:"long"}[tt]||"short";
  let base=c.b,defs="",stripeC=null,stripeH=C.type==="adult"||C.type==="elder"?6:4.6;
  if(C.stripe&&!C.dress)stripeC=col(C.stripe);
  if(C.dress&&C.dressPat){const id=uid("dp"),pc=col(C.patC,"#FFFDF4");defs+=`<pattern id="${id}" width="8" height="8" patternUnits="userSpaceOnUse"><rect width="8" height="8" fill="${c.b}"/>${C.dressPat==="flowers"?`<g transform="translate(2 2)">${[0,72,144,216,288].map(r=>`<circle cy="-1.1" r=".8" fill="${pc}" transform="rotate(${r})"/>`).join("")}<circle r=".5" fill="#F6C742"/></g><circle cx="6.4" cy="6.2" r=".6" fill="${pc}" opacity=".7"/>`:`<circle cx="2" cy="2" r="1" fill="${pc}"/><circle cx="6" cy="6" r="1" fill="${pc}"/>`}</pattern>`;base=`url(#${id})`}
  let cuff=null;if(C.stripe&&sleeve==="long")cuff=cloth(C.stripe);
  if(C.coat)return {tt,c,sleeve:"long",base,defs,cuff:null,sc:cloth(C.coat===true?"#FBFBF7":C.coat),stripeC:null,stripeH};
  return {tt,c,sleeve,base,defs,cuff,stripeC,stripeH}}
function botInfo(C){if(C.dress)return {legs:"skin"};const bt=C.bottomType||"pants";const c=cloth(C.bottom||"#3E4A78");
  return {bt,c,legs:bt==="pants"?"pants":bt==="shorts"?"shorts":"skin",cuff:null}}

function torsoSvg(K,top,bot){const {T,C,t}=K;let s=top.defs?`<defs>${top.defs}</defs>`:"",sb="";const c=top.c;const W=d=>t?warpD(d,K.bm):d;const bs=K.bs;
  if(top.tt==="dress"){let hemY=K.T.dressHem+K.by,dw=T.dressW;if(K.lp==="seat"||K.wc){hemY=Math.min(hemY,K.seatY+T.legW*.9);dw=T.dressW*.95}
    const d=W(K.lp==="sit"?dressSitD(K,T.hemW*1.4):dressD(K,hemY,dw));if(K.lp==="sit")hemY=-T.H*.018,dw=T.hemW*1.4+2;
    s+=volIn(P1(d),{base:top.base,dark:c.d,line:c.l,lw:1.15,sx:4,sy:5,b:"soft",op:.75,drop:c.l,dw:.85,rim:lt(c.b,.45),ro:.5,rw:1.8});
    const wy=T.waY+K.by;s+=line(`M${F(bs(-T.waW+.4))} ${F(wy)} Q${F(bs(0))} ${F(wy+1.6)} ${F(bs(T.waW-.4))} ${F(wy)}`,c.d,1.1,.8);
    s+=line(`M${F(bs(-dw*.45))} ${F(hemY-2)} q${F(1)} ${F(-(hemY-wy)*.35)} ${F(dw*.2)} ${F(-(hemY-wy)*.7)} M${F(bs(dw*.3))} ${F(hemY-1.5)} q${F(-.5)} ${F(-(hemY-wy)*.4)} ${F(-dw*.12)} ${F(-(hemY-wy)*.7)}`,c.d,1,.45);
    const col2=C.collar?hex6(col(C.collar)):"#FFFDF6";const sy=K.shY,cx=bs(0);
    s+=[-1,1].map(sd=>{const k=sd>0?1-.3*t:1;return `<path d="M${F(cx)} ${F(sy-.2)} C${F(cx+sd*2*k)} ${F(sy+3.4)} ${F(cx+sd*6.4*k)} ${F(sy+3.6)} ${F(cx+sd*7.2*k)} ${F(sy+.2)} C${F(cx+sd*7*k)} ${F(sy-1.6)} ${F(cx+sd*5.4*k)} ${F(sy-2.4)} ${F(cx+sd*4.8*k)} ${F(sy-2.2)}Z" fill="${col2}" stroke="${dk(col2,.3)}" stroke-width=".9"/>`}).join("");
    if(C.sash!==false){const sc=cloth(C.sash||lt(c.b,.55));s+=`<path d="${W(`M${F(-T.waW+.2)} ${F(wy-1.2)} Q0 ${F(wy+.6)} ${F(T.waW-.2)} ${F(wy-1.2)} L${F(T.waW)} ${F(wy+1.4)} Q0 ${F(wy+3.2)} ${F(-T.waW)} ${F(wy+1.4)}Z`)}" fill="${sc.b}" stroke="${sc.l}" stroke-width=".8"/>`+bowSvg(bs(T.waW*.55),wy+.6,sc.b,.5)}
    return {bottom:"",top:s}}
  /* alt parça (pantolon üstü / etek) */
  const s0=s;s="";
  if(bot.bt==="skirt"&&K.fw){const hy=K.hem-1,sk=bot.c,ky=K.seatY-T.legW*.42,kx=T.hipX*1.25+K.fw,dw=T.hemW+2.4,by=K.seatY+T.legW*.55;
    s+=`<path d="${W(`M${F(-T.hemW+.6)} ${F(hy)} L${F(T.hemW-.6)} ${F(hy)} C${F(T.hemW+4)} ${F(hy+1)} ${F(kx-2)} ${F(ky-T.legW*.75)} ${F(kx+2.6)} ${F(ky-T.legW*.5)} C${F(kx+4.6)} ${F(ky-T.legW*.2)} ${F(kx+4.2)} ${F(ky+T.legW*.55)} ${F(kx+1.8)} ${F(ky+T.legW*.8)} Q${F(kx*.4)} ${F(by+1.6)} ${F(-dw)} ${F(by)} C${F(-dw-.6)} ${F(by-4)} ${F(-T.hemW-1)} ${F(hy+4)} ${F(-T.hemW+.6)} ${F(hy)}Z`)}" fill="${sk.b}" stroke="${sk.l}" stroke-width="1.1"/>`
      +soft(`<path d="${W(`M${F(T.hemW*.2)} ${F(ky+2)} Q${F(kx*.6)} ${F(ky+T.legW*.1)} ${F(kx+2.4)} ${F(ky+T.legW*.6)} Q${F(kx*.4)} ${F(by+1)} ${F(-dw+2)} ${F(by-.4)}Z`)}" fill="${sk.d}"/>`,.6)
      +line(W(`M${F(T.hemW*.4)} ${F(hy+3)} Q${F(kx*.55)} ${F(ky-T.legW*.3)} ${F(kx+1)} ${F(ky-T.legW*.1)} M${F(-T.hemW*.3)} ${F(hy+3)} l${F(-.6)} ${F(by-hy-4)}`),sk.d,.9,.5)}
  else if(bot.bt==="skirt"){const hy=K.hem-1,sk=bot.c,sit=K.lp==="sit",dw=T.hemW+5,hemY=K.lp==="seat"?K.seatY+T.legW*.9:sit?-T.H*.042:K.hem+T.H*.13;const dw2=sit?T.hemW*1.4-1.2:dw;
    s+=`<path d="${W(`M${F(-T.hemW+.6)} ${F(hy)} L${F(T.hemW-.6)} ${F(hy)} C${F(T.hemW+1)} ${F(hy+4)} ${F(dw2-1)} ${F(hemY-3)} ${F(dw2)} ${F(hemY)} ${hemPath([dw2,dw2/3,-dw2/3,-dw2],hemY)} C${F(-dw2+1)} ${F(hemY-3)} ${F(-T.hemW-1)} ${F(hy+4)} ${F(-T.hemW+.6)} ${F(hy)}Z`)}" fill="${sk.b}" stroke="${sk.l}" stroke-width="1.1"/>`+soft(`<path d="${W(`M${F(dw2*.3)} ${F(hy+2)} L${F(dw2-1.4)} ${F(hemY-.6)} L${F(dw2*.35)} ${F(hemY+.6)}Z`)}" fill="${sk.d}"/>`,.7)+line(W(`M${F(-dw2*.35)} ${F(hemY)} l${F(1.2)} ${F(-(hemY-hy)*.7)} M${F(dw2*.1)} ${F(hemY+.6)} l${F(-.4)} ${F(-(hemY-hy)*.7)}`),sk.d,.9,.5)}
  else if(bot.c){const hy=K.hem-2.4,cy=K.lp==="sit"?K.hipY+T.H*.05:K.lp==="seat"?K.hipY+T.legW*.4:K.hipY+T.H*.08,w=T.hemW-.2;
    s+=`<path d="${W(`M${F(-w)} ${F(hy)} H${F(w)} C${F(w+.4)} ${F(hy+4)} ${F(w-.4)} ${F(cy-2)} ${F(w-2)} ${F(cy)} L${F(1.4)} ${F(cy)} Q0 ${F(cy-1.6)} ${F(-1.4)} ${F(cy)} L${F(-w+2)} ${F(cy)} C${F(-w+.4)} ${F(cy-2)} ${F(-w-.4)} ${F(hy+4)} ${F(-w)} ${F(hy)}Z`)}" fill="${bot.c.b}" stroke="${bot.c.l}" stroke-width="1.1"/>`+soft(`<path d="${W(`M${F(w*.35)} ${F(hy+1)} H${F(w-.6)} L${F(w-2)} ${F(cy-.5)} H${F(w*.4)}Z`)}" fill="${bot.c.d}"/>`,.6)+line(`M${F(bs(.3))} ${F(hy+1.4)} L${F(bs(.2))} ${F(cy-2.2)}`,bot.c.l,.7,.45)+line(W(`M${F(-w+1.6)} ${F(hy+2.4)} q${F(2.4)} ${F(1.4)} ${F(4)} ${F(-.6)} M${F(w-1.6)} ${F(hy+2.4)} q${F(-2.4)} ${F(1.4)} ${F(-4)} ${F(-.6)}`),bot.c.l,.6,.4)}
  sb=s;s=s0;
  /* üst */
  const d=W(torsoD(K));const sy=K.shY,hy=K.hem,cx=bs(0);
  let inner="";if(top.stripeC){const h=top.stripeH;for(let y=sy+h*.55;y<hy+3;y+=h)inner+=line(`M${F(-T.shW-3)} ${F(y)} Q${F(cx)} ${F(y+2.2)} ${F(T.shW+3)} ${F(y-.2*t)}`,top.stripeC,h/2)}
  s+=volIn(P1(d),{base:top.base,dark:c.d,line:c.l,lw:1.15,sx:4,sy:5,b:"soft",op:.75,inner,drop:c.l,dw:.85,rim:lt(c.b,.45),ro:.5,rw:1.8});
  /* kumaş kıvrımları: koltuk altından bele inen yumuşak çekme + bel hizasında kısa büzgüler */
  if(K.pose!=="lie"){const wy=T.waY+K.by,f=[];for(const sd of [-1,1]){const k=sd>0?1-.3*t:1,x0=sd*(T.shW-T.H*.022)*k,x1=sd*(T.waW-T.H*.03)*k;
      f.push(`M${F(bs(x0))} ${F(sy+T.H*.05)} Q${F(bs(x0*.9))} ${F((sy+wy)/2+T.H*.02)} ${F(bs(x1))} ${F(wy+T.H*.01)}`,`M${F(bs(x1*.92))} ${F(wy+T.H*.03)} q${F(-sd*T.H*.02)} ${F(T.H*.012)} ${F(-sd*T.H*.04)} ${F(T.H*.008)}`)}
    s+=line(f.join(" "),c.d,.7,.5)}
  if(top.tt==="tee"||top.tt==="sweater")s+=line(`M${F(bs(-T.nw-.6))} ${F(sy-2)} Q${F(cx)} ${F(sy+2.6)} ${F(bs(T.nw+.6))} ${F(sy-2)}`,top.tt==="sweater"?c.d:lt(c.b,.3),1.6,.9)+line(`M${F(bs(-T.nw-.6))} ${F(sy-1.2)} Q${F(cx)} ${F(sy+3.4)} ${F(bs(T.nw+.6))} ${F(sy-1.2)}`,c.l,.7,.5);
  if(C.rib&&top.tt==="sweater"){const bh=T.H*.035;/* örgü etek bandı: sık kaburga */
    s+=`<path d="${W(`M${F(-T.hemW)} ${F(hy-bh)} Q0 ${F(hy-bh+2.4)} ${F(T.hemW)} ${F(hy-bh)} L${F(T.hemW)} ${F(hy)} Q0 ${F(hy+2.4)} ${F(-T.hemW)} ${F(hy)}Z`)}" fill="${mix(c.b,c.d,.45)}" stroke="${c.l}" stroke-width=".7" stroke-opacity=".6"/>`
      +Array.from({length:17},(_,i)=>{const f=-.92+i*.115,x=bs(f*T.hemW),yb=hy-bh+1.2*(1-f*f)+.3;return line(`M${F(x)} ${F(yb)} v${F(bh+.4*(1-f*f)-.4)}`,c.l,.5,.45)}).join("")}
  else if(top.tt==="sweater"||top.tt==="hoodie"){s+=`<path d="${W(`M${F(-T.hemW)} ${F(hy-2.6)} Q0 ${F(hy-.2)} ${F(T.hemW)} ${F(hy-2.6)} L${F(T.hemW)} ${F(hy)} Q0 ${F(hy+2.4)} ${F(-T.hemW)} ${F(hy)}Z`)}" fill="${c.d}" opacity=".55"/>`+[-.7,-.35,0,.35,.7].map(f=>line(`M${F(bs(f*T.hemW))} ${F(hy-2+Math.abs(f)*-.6)} v2.2`,c.l,.6,.4)).join("")}
  if(top.tt==="hoodie"){const pw=T.hemW*.62,py=hy-T.H*.1;s+=`<path d="M${F(bs(-pw))} ${F(hy-2.8)} L${F(bs(-pw*.72))} ${F(py)} H${F(bs(pw*.72))} L${F(bs(pw))} ${F(hy-2.8)}Z" fill="${c.m}" stroke="${c.l}" stroke-width=".9" opacity=".95"/>`+line(`M${F(bs(-pw*.72))} ${F(py)} H${F(bs(pw*.72))}`,lt(c.b,.3),.8,.6)}
  if(top.tt==="shirt"||top.tt==="cardigan"){const col2=top.tt==="shirt"?(C.collar?hex6(col(C.collar)):lt(c.b,.25)):null;
    if(top.tt==="cardigan"){const inn=cloth(C.inner||"#FFFDF6"),lie=K.pose==="lie",vy=sy+T.H*(lie?.04:.1);
      /* yatarken derin V yerine yumuşak yuvarlak yaka (sert beyaz üçgen oluşmasın) */
      s+=lie?`<path d="M${F(bs(-T.nw+.2))} ${F(sy-2)} Q${F(cx)} ${F(vy+2.2)} ${F(bs(T.nw-.2))} ${F(sy-2)} Q${F(cx)} ${F(sy+.6)} ${F(bs(-T.nw+.2))} ${F(sy-2)}Z" fill="${mix(inn.b,c.b,.3)}" stroke="${c.l}" stroke-width=".8" stroke-opacity=".7"/>`+soft(line(`M${F(bs(-T.nw+1))} ${F(sy-1)} Q${F(cx)} ${F(vy)} ${F(bs(T.nw-1))} ${F(sy-1)}`,inn.d,1.4),.5)
        :`<path d="M${F(bs(-T.nw+.4))} ${F(sy-2)} L${F(cx)} ${F(vy)} L${F(bs(T.nw-.4))} ${F(sy-2)} Q${F(cx)} ${F(sy+1)} ${F(bs(-T.nw+.4))} ${F(sy-2)}Z" fill="${inn.b}" stroke="${inn.l}" stroke-width=".8"/>`;
      s+=line(`M${F(cx)} ${F(vy+(lie?1.4:0))} L${F(cx)} ${F(hy+1.4)}`,c.l,1,.8)+[0,1,2].map(i=>`<circle cx="${F(cx+1.6)}" cy="${F(sy+T.H*.13+i*T.H*.06)}" r="${F(T.H*.009)}" fill="${lt(c.b,.6)}" stroke="${c.l}" stroke-width=".5"/>`).join("")}
    else{s+=line(`M${F(cx)} ${F(sy+.5)} L${F(cx)} ${F(hy+1.4)}`,c.d,1,.7)+[0,1,2].map(i=>`<circle cx="${F(cx+1)}" cy="${F(sy+T.H*.06+i*T.H*.065)}" r="${F(T.H*.007)}" fill="${lt(c.b,.6)}" stroke="${c.l}" stroke-width=".5"/>`).join("");
      s+=[-1,1].map(sd=>{const k=sd>0?1-.3*t:1;return `<path d="M${F(cx+sd*T.nw*.2)} ${F(sy-.6)} L${F(cx+sd*T.nw*1.4*k)} ${F(sy+T.H*.035)} L${F(cx+sd*T.nw*1.3*k)} ${F(sy-2.8)}Z" fill="${col2}" stroke="${dk(col2,.35)}" stroke-width=".8" stroke-linejoin="round"/>`}).join("")}}
  if(C.print&&!C.coat&&top.tt!=="cardigan")s+=`<g transform="translate(${F(cx+(C.printX||0))} ${F(sy+T.H*(top.tt==="hoodie"?.075:.1))}) scale(${F(1-.22*t)} 1)">${printSvg(C.print,0,0,T.H/100*(C.printS||1))}</g>`;
  if(top.tt==="tee"&&!top.stripeC)s+=line(`M${F(bs(-T.hemW+1))} ${F(hy-1.3)} Q${F(cx)} ${F(hy+.9)} ${F(bs(T.hemW-1))} ${F(hy-1.3)}`,lt(c.b,.35),.7,.55);
  if(top.tt==="vest"||C.vest){const vc=cloth(C.vestC||C.vest||"#C9603E");const vw=T.shW-2.2;
    s+=`<path d="${W(`M${F(-T.nw-1)} ${F(sy-2.2)} ${K.pose==="lie"?"Q":"L"}0 ${F(sy+T.H*(K.pose==="lie"?.1:.14))} ${K.pose==="lie"?"":"L"}${F(T.nw+1)} ${F(sy-2.2)} C${F(vw)} ${F(sy-1)} ${F(vw+.6)} ${F(sy+4)} ${F(vw-1)} ${F(sy+T.H*.1)} C${F(T.waW+.4)} ${F(sy+T.H*.18)} ${F(T.hemW+.6)} ${F(hy-3)} ${F(T.hemW+.6)} ${F(hy+.6)} Q0 ${F(hy+3)} ${F(-T.hemW-.6)} ${F(hy+.6)} C${F(-T.hemW-.6)} ${F(hy-3)} ${F(-T.waW-.4)} ${F(sy+T.H*.18)} ${F(-vw+1)} ${F(sy+T.H*.1)} C${F(-vw-.6)} ${F(sy+4)} ${F(-vw)} ${F(sy-1)} ${F(-T.nw-1)} ${F(sy-2.2)}Z`)}" fill="${vc.b}" stroke="${vc.l}" stroke-width="1.1"/>`
      +soft(`<path d="${W(`M${F(T.hemW*.4)} ${F(sy+T.H*.16)} C${F(T.waW)} ${F(sy+T.H*.2)} ${F(T.hemW)} ${F(hy-3)} ${F(T.hemW-.4)} ${F(hy)} L${F(T.hemW*.5)} ${F(hy+.6)}Z`)}" fill="${vc.d}"/>`,.7)
      +Array.from({length:4},(_,i)=>line(W(`M${F(-T.hemW+2+i*1.2)} ${F(sy+T.H*.16+i*T.H*.045)} l1.4 1.2 l1.4 -1.2 M${F(T.hemW-5.4-i*1.2)} ${F(sy+T.H*.16+i*T.H*.045)} l1.4 1.2 l1.4 -1.2`),vc.d,.7,.6)).join("")}
  return {bottom:sb,top:s}}

/* göğüs baskısı (yazı/logo yok; basit simge) */
function printSvg(kind,x,y,k){const g=b=>`<g transform="translate(${F(x)} ${F(y)}) scale(${F(k)})">${b}</g>`;
  switch(kind){
   case "star":return g(`<path d="${starPath(4.4)}" fill="#F8CF4A" stroke="#C8901E" stroke-width=".7" stroke-linejoin="round"/><path d="M-1.4 -1.6 l1 -1.8" stroke="#fff" stroke-width=".7" opacity=".7" stroke-linecap="round"/>`);
   case "heart":return g(`<path d="M0 3.6 C-5 .4 -4.4 -4.4 0 -1.8 C4.4 -4.4 5 .4 0 3.6Z" fill="#EE5A78" stroke="#A8304C" stroke-width=".7"/><ellipse cx="-1.8" cy="-1.4" rx="1" ry=".6" fill="#fff" opacity=".7"/>`);
   case "flower":return g([0,72,144,216,288].map(r=>`<ellipse cy="-2.4" rx="1.7" ry="2.3" fill="#FFFDF6" stroke="#D8B8C8" stroke-width=".5" transform="rotate(${r})"/>`).join("")+`<circle r="1.5" fill="#F6C742" stroke="#C8901E" stroke-width=".5"/>`);
   case "rocket":return g(`<path d="M-2 3.4 l-1.8 2 v-3.4Z M2 3.4 l1.8 2 v-3.4Z" fill="#E4574F"/><path d="M0 -5.6 C2.8 -3 2.6 1 2 3.8 H-2 C-2.6 1 -2.8 -3 0 -5.6Z" fill="#FFFDF6" stroke="#8A8FA8" stroke-width=".6"/><circle cy="-1" r="1.2" fill="#6FB4E8" stroke="#3E6E9E" stroke-width=".5"/><path d="M-1.2 4 Q0 7.4 1.2 4Z" fill="#F6A83A"/><path d="M-2.4 -3 Q0 -4.4 2.4 -3" stroke="#E4574F" stroke-width=".9" fill="none"/>`);
   case "sun":return g(Array.from({length:8},(_,i)=>`<path d="M0 -3.6 L0 -5.4" stroke="#F6A83A" stroke-width="1" stroke-linecap="round" transform="rotate(${i*45})"/>`).join("")+`<circle r="2.8" fill="#F8CF4A" stroke="#D8901E" stroke-width=".6"/><path d="M-1.2 .4 q1.2 1 2.4 0" stroke="#9A5A10" stroke-width=".5" fill="none"/>`);
   case "car":return g(`<path d="M-5 1.6 V-.4 C-5 -1.4 -4.2 -1.6 -3.4 -1.8 L-2 -3.8 H2.2 L3.6 -1.8 C4.6 -1.6 5 -1 5 -.2 V1.6Z" fill="#4F8FD8" stroke="#2E5A9A" stroke-width=".6"/><path d="M-1.6 -3.2 H1.8 L2.8 -1.8 H-2.6Z" fill="#CFE6FA"/><circle cx="-2.8" cy="1.8" r="1.2" fill="#3C4152"/><circle cx="2.8" cy="1.8" r="1.2" fill="#3C4152"/>`);
   case "rainbow":return g(["#EE6A62","#F4A04A","#F4D35A","#79C27D","#5AA3DE"].map((c,i)=>`<path d="M${-5+i*.9} 2 A${5-i*.9} ${5-i*.9} 0 0 1 ${5-i*.9} 2" stroke="${c}" stroke-width=".95" fill="none"/>`).join(""));
   case "paw":return g(`<ellipse cy="1.2" rx="2.4" ry="2" fill="#8A5A3A"/>${[[-2.6,-1.6],[-.9,-3],[.9,-3],[2.6,-1.6]].map(([a,b])=>`<ellipse cx="${a}" cy="${b}" rx=".9" ry="1.1" fill="#8A5A3A"/>`).join("")}`);
  }return ""}
/* kapüşon: başın arkasında kumaş kıvrımları, iki omzun üstünden görünür */
function hoodBack(K,top){const {T,t}=K,c=top.c,sy=K.shY,W=T.shW*.94,y0=sy+1.4;
  const d=`M${F(-W)} ${F(y0)} C${F(-W-.6)} ${F(y0-5.6)} ${F(-W*.66)} ${F(sy-9.2)} ${F(-W*.3)} ${F(sy-8.4)} C${F(-W*.1)} ${F(sy-8)} ${F(W*.1)} ${F(sy-8)} ${F(W*.3)} ${F(sy-8.4)} C${F(W*.66)} ${F(sy-9.2)} ${F(W+.6)} ${F(y0-5.6)} ${F(W)} ${F(y0)} Q0 ${F(y0+3)} ${F(-W)} ${F(y0)}Z`;
  const Wd=x=>t?warpD(x,K.bm):x;
  return `<path d="${Wd(d)}" fill="${c.b}" stroke="${c.l}" stroke-width="1.1"/>`+soft(`<path d="${Wd(`M${F(-W*.8)} ${F(y0-1)} C${F(-W*.6)} ${F(sy-5)} ${F(W*.6)} ${F(sy-5)} ${F(W*.8)} ${F(y0-1)} Q0 ${F(y0+1)} ${F(-W*.8)} ${F(y0-1)}Z`)}" fill="${c.d}"/>`,.8)
    +line(Wd(`M${F(-W*.86)} ${F(y0-2)} C${F(-W*.8)} ${F(sy-4.4)} ${F(-W*.62)} ${F(sy-6.6)} ${F(-W*.44)} ${F(sy-7.2)} M${F(-W*.72)} ${F(y0-.4)} C${F(-W*.64)} ${F(sy-2.6)} ${F(-W*.5)} ${F(sy-4.4)} ${F(-W*.36)} ${F(sy-5)} M${F(W*.86)} ${F(y0-2)} C${F(W*.8)} ${F(sy-4.4)} ${F(W*.62)} ${F(sy-6.6)} ${F(W*.44)} ${F(sy-7.2)} M${F(W*.72)} ${F(y0-.4)} C${F(W*.64)} ${F(sy-2.6)} ${F(W*.5)} ${F(sy-4.4)} ${F(W*.36)} ${F(sy-5)}`),c.l,.8,.55)
    +line(Wd(`M${F(-W*.9)} ${F(y0-3.4)} C${F(-W*.8)} ${F(sy-7.4)} ${F(-W*.55)} ${F(sy-8.6)} ${F(-W*.34)} ${F(sy-8.2)}`),c.h,.9,.5)}
function hoodFront(K,top){const {T}=K,c=top.c,sy=K.shY,cx=K.bs(0),bs=K.bs;
  const d=`M${F(bs(-T.nw-3.4))} ${F(sy-1.8)} Q${F(cx)} ${F(sy+4.2)} ${F(bs(T.nw+3.4))} ${F(sy-1.8)}`;
  return line(d,c.l,T.H*.028+2)+line(d,c.m,T.H*.028)+line(d,c.h,.8,.55)+line(`M${F(cx-1.6)} ${F(sy+1.8)} q-.6 ${F(T.H*.04)} .2 ${F(T.H*.07)} M${F(cx+1.8)} ${F(sy+1.8)} q.6 ${F(T.H*.035)} -.2 ${F(T.H*.065)}`,"#FFFDF6",1,.95)+`<circle cx="${F(cx-1.4)}" cy="${F(sy+1.8+T.H*.07)}" r=".8" fill="#FFFDF6"/><circle cx="${F(cx+1.6)}" cy="${F(sy+1.8+T.H*.065)}" r=".8" fill="#FFFDF6"/>`}

/* uzun önlük / palto (doktor, öğretmen vb.) */
