/* ---- cast/doktor.js ---- */
/* Doktor — beyaz önlüklü, stetoskoplu doktor (HUMAN motoru). o.female:true → kadın doktor */
(()=>{
const steth=K=>{const {T}=K;if(K.C.pose==="crawl")return "";const bs=K.bs,sy=K.shY,f=n=>(+n).toFixed(1);
  const a=-T.nw-.4,b=T.nw+.4,yJ=sy+T.H*(K.lp==="seat"||K.lp==="sit"?.15:.19),xJ=bs(-1.2),xP=bs(3.8),yP=yJ+T.H*.085;
  const tube=`M${f(bs(a))} ${f(sy-2.6)} C${f(bs(a-3.4))} ${f(sy+4)} ${f(bs(-5.4))} ${f(yJ-4)} ${f(xJ)} ${f(yJ)} M${f(bs(b))} ${f(sy-2.6)} C${f(bs(b+3.2))} ${f(sy+4)} ${f(bs(3.6))} ${f(yJ-4)} ${f(xJ)} ${f(yJ)} M${f(xJ)} ${f(yJ)} C${f(xJ-1.4)} ${f(yJ+5)} ${f(xP-2)} ${f(yP-4)} ${f(xP)} ${f(yP-2.4)}`;
  return `<g fill="none" stroke-linecap="round"><path d="${tube}" stroke="#2E3A56" stroke-width="2.6"/><path d="${tube}" stroke="#5A6A8E" stroke-width="1.5"/><path d="${tube}" stroke="#A8B6D8" stroke-width=".5" opacity=".7" transform="translate(-.4 -.3)"/></g>`
   +`<circle cx="${f(xJ)}" cy="${f(yJ)}" r="1" fill="#C9D2E2" stroke="#6A7488" stroke-width=".5"/>`
   +`<g transform="translate(${f(xP)} ${f(yP)})"><circle r="3" fill="#D8DEE8" stroke="#6A7488" stroke-width=".8"/><circle r="1.8" fill="#AEB8CA"/><ellipse cx="-.9" cy="-1" rx="1" ry=".6" fill="#fff" opacity=".85"/></g>`
   +(K.pose==="lie"?"":`<g transform="translate(${f(bs(-T.shW*.52))} ${f(sy+T.H*.1)})"><rect x="-1.6" y="-4.4" width="1.3" height="6" rx=".6" fill="#4F8FD8" stroke="#2E5A9A" stroke-width=".4"/><rect x="-1.6" y="-4.6" width="1.3" height="1.2" rx=".5" fill="#2E5A9A"/><rect x=".4" y="-3.6" width="1.2" height="5" rx=".55" fill="#E4574F" stroke="#A8304C" stroke-width=".4"/><path d="M.6 -3.6 v-.9 h.8 v.9" fill="#F6C742"/>`
   /* göğüs cebi: kalemler cepten çıkar */
   +`<path d="M-3.4 -.6 h6.8 v5 q0 1.1 -1.1 1.1 h-4.6 q-1.1 0 -1.1 -1.1Z" fill="#EDEEE8" stroke="#A9ABA2" stroke-width=".7"/><path d="M-3 .6 h6" stroke="#A9ABA2" stroke-width=".45" stroke-dasharray=".9 .7"/><path d="M-3.4 -.5 h6.8" stroke="#fff" stroke-width=".6"/></g>`)};
const M={name:"Doktor",type:"adult",skin:"t6",hair:"short",hairC:"siyah",eyeC:"#2E1A10",faceShape:"oval",eyeShape:"round",browW:1.15,noseS:1.12,build:"regular",hF:1.02,glasses:"#6A4A2A",
  top:"#6FA7C8",topType:"tee",bottom:"#3E4A78",bottomType:"pants",coat:true,shoes:"#5A4A3A",addFront:steth};
const W={name:"Doktor",type:"adult",skin:"t2",hair:"bun",hairC:"kestane",eyeC:"#4E6A3A",lash:true,faceShape:"heart",eyeShape:"almond",browW:.95,noseS:.95,build:"slim",hF:.98,
  top:"#9C7BD8",topType:"tee",bottom:"#3E4A78",bottomType:"pants",coat:true,shoes:"#FFFDF6",sneaker:true,addFront:steth};
HUMAN.presets.doktor=o=>o.female?W:M;
CAST.doktor=o=>HUMAN.draw(o,"doktor");
CAST.doktor.meta={name:"Doktor",h:137,poses:HUMAN.POSES.filter(p=>p!=="crawl"),note:"çocuk doktoru; varsayılan: koyu ten, kısa siyah saç, kahve gözlük, beyaz önlük (yaka, cep) + açık mavi iç + lacivert pantolon, boynunda lacivert stetoskop (göğüste gümüş kulaklık ucu), cepte iki renkli kalem. o.female:true → kadın doktor: açık ten, kestane topuz, yeşil göz, lila iç, beyaz spor ayakkabı. Tüm HUMAN pozları + 11 ifade (calm = güven veren, think = muayene). hold: o.hold (ör. termometre/ilaç PROPS) iki elde."};
})();

