const drop=(x,y,s,rot=0)=>`<g transform="translate(${f1(x)} ${f1(y)}) rotate(${rot}) scale(${s})"><path d="M0 -5 C2.6 -1.2 3.4 1 3.4 2.4 A3.4 3.4 0 0 1 -3.4 2.4 C-3.4 1 -2.6 -1.2 0 -5Z" fill="#9ED8F6" stroke="#4E9CCB" stroke-width=".7"/><ellipse cx="-1.2" cy="1.6" rx=".9" ry="1.3" fill="#fff" opacity=".85"/></g>`;
const spark=(x,y,r,c="#FFD85A")=>`<path transform="translate(${f1(x)} ${f1(y)})" d="M0 ${-r} Q${r*.18} ${-r*.18} ${r} 0 Q${r*.18} ${r*.18} 0 ${r} Q${-r*.18} ${r*.18} ${-r} 0 Q${-r*.18} ${-r*.18} 0 ${-r}Z" fill="${c}" stroke="#E0A020" stroke-width=".4"/>`;
