/* yüz: göz, kaş, ağız, allık, ek işaretler. F: yüz parametreleri (bkz. karakter dosyası) */
function face(m,F){const M=MOOD[moodOf(m)],r=F.er,cx=F.cx||0,fr=F.far||1;
  const irisDefs=`<defs><radialGradient id="${F.gid}ir" cx=".5" cy=".75" r=".75"><stop offset="0" stop-color="${lt(F.iris,.45)}"/><stop offset=".55" stop-color="${F.iris}"/><stop offset="1" stop-color="${F.iris}" stop-opacity="0"/></radialGradient></defs>`;
  const xl=cx-F.ex,xr=cx+F.ex*(F.farx||1),y=F.ey,bg=(F.bgap||1.45)*r;
  let s=irisDefs;
  const blA=M.bl*(F.blk||1),bc=M.red?"#FF5E6E":"#FF86A0";
  s+=soft(`<ellipse cx="${f1(cx-F.bdx)}" cy="${f1(F.bly)}" rx="${f1(F.blr*(M.fx==="shy"?1.25:1))}" ry="${f1(F.blr*.62)}" fill="${bc}"/><ellipse cx="${f1(cx+F.bdx*(F.bfx||F.farx||1))}" cy="${f1(F.bly)}" rx="${f1(F.blr*fr*(M.fx==="shy"?1.25:1))}" ry="${f1(F.blr*.62*fr)}" fill="${bc}"/>`,clamp(blA,0,1));
  if(M.fx==="shy")s+=[-1,1].map(sd=>{const bx=cx+sd*F.bdx*(sd>0?(F.bfx||F.farx||1):1);return [-.5,0,.5].map(k=>`<path d="M${f1(bx+k*F.blr*.9-F.blr*.18)} ${f1(F.bly+F.blr*.3)} l${f1(F.blr*.36)} ${f1(-F.blr*.6)}" stroke="#E85A7A" stroke-width="${f1(F.blr*.16)}" stroke-linecap="round" opacity=".7"/>`).join("")}).join("");
  const eyes=eye1(xl,y,r,M,F,-1)+eye1(xr,y,r*fr,M,F,1);
  s+=M.e==="open"||M.e==="big"?`<g class="blink">${eyes}</g>`:eyes;
  s+=brow(xl,y-bg,r,M.br,F,-1)+brow(xr,y-bg*fr,r*fr,M.br2||M.br,F,1);
  const mx=cx+(F.mdx||0)+(M.mo==="tiny"?-F.mw*.25:0);
  const ms=M.ms||[1,1];
  s+=`<g transform="translate(${f1(mx)} ${f1(F.my)})${ms[0]!==1||ms[1]!==1?` scale(${ms[0]} ${ms[1]})`:""}">${mouthA(M.mo,F)}</g>`;
  const T=F.top||[cx+14,y-14],D=F.side||[cx+F.ex+r*2.2,y-r];
  switch(M.fx){
   case "tear":s+=drop(xl+r*.2,y+r*1.75,r*.2)+`<path d="M${f1(xl+r*.25)} ${f1(y+r*.8)} q${f1(-r*.1)} ${f1(r*.35)} 0 ${f1(r*.5)}" stroke="#7CC4EE" stroke-width="${f1(r*.2)}" fill="none" stroke-linecap="round" opacity=".8"/>`;break;
   case "sweat":s+=drop(D[0],D[1],r*.24,-18);break;
   case "spark":s+=`<g class="tw">${spark(T[0],T[1],r*.7)}</g><g class="tw" style="animation-delay:-1.1s">${spark(T[0]-r*2.2,T[1]-r*1.1,r*.45)}</g>`;break;
   case "pop":{const L=[-55,-28,0].map(a=>{const c=Math.cos(a*Math.PI/180),sn=Math.sin(a*Math.PI/180);return `M${f1(T[0]+c*r*.8)} ${f1(T[1]+sn*r*.8)} l${f1(c*r*1.2)} ${f1(sn*r*1.2)}`}).join(" ");
     s+=`<path d="${L}" stroke="#7A5A3A" stroke-width="${f1(r*.5)}" stroke-linecap="round" opacity=".55"/><path d="${L}" stroke="#FFF6D8" stroke-width="${f1(r*.3)}" stroke-linecap="round"/>`;break}
   case "vein":{const vs=r*.95,arm=`M.28 -1 Q.3 -.3 1 -.28`,V=[0,90,180,270].map(a=>`<path transform="rotate(${a})" d="${arm}"/>`).join("");
     const pf=(dx,dy,k)=>`<path transform="translate(${f1(T[0]+dx)} ${f1(T[1]+dy)}) scale(${f1(r*.2*k)})" d="M-4 2 C-6.2 2 -6.2 -1.2 -3.8 -1.6 C-3.8 -4.4 -.6 -5 .4 -2.8 C1.6 -4.6 4.6 -3.8 4.2 -1.2 C6.2 -.8 6 2 3.8 2Z" fill="#FFB38A" stroke="#E0613C" stroke-width="1.1"/><path transform="translate(${f1(T[0]+dx)} ${f1(T[1]+dy)}) scale(${f1(r*.2*k)})" d="M-3.4 -1.4 C-3 -3.4 -1 -3.8 0 -2.4" stroke="#FFE6D6" stroke-width="1" fill="none" stroke-linecap="round"/>`;
     s+=`<g class="tw">${pf(-r*2.2,-r*.2,1)}${pf(-r*1.1,-r*1.5,.7)}</g><g class="beat"><g transform="translate(${f1(T[0]+r*.9)} ${f1(T[1]+r*.5)}) scale(${f1(vs)})"><g fill="none" stroke="#B3262B" stroke-width=".62" stroke-linecap="round">${V}</g><g fill="none" stroke="#FF5A4E" stroke-width=".34" stroke-linecap="round">${V}</g></g></g>`;break}
   case "zzz":s+=`<g class="float">${zee(T[0],T[1],r*.26)}${zee(T[0]+r*1.5,T[1]-r*1.6,r*.19)}</g>`;break;
   case "dots":s+=`<g class="q">${[[0,0,.2],[r*.9,-r*.9,.28],[r*2.1,-r*2,.4]].map(([dx,dy,k])=>`<circle cx="${f1(T[0]+dx)}" cy="${f1(T[1]+dy)}" r="${f1(r*k*1.4)}" fill="#fff" stroke="#9AA6C8" stroke-width="${f1(r*.12)}"/>`).join("")}</g>`;break;
  }
  return s}

/* sallanan kol: omuz (sx,sy) .wave dönme merkezine (kutunun %20,%90) oturur; W,H kolu kapsamalı */
const waveG=(inner,sx,sy,W=60,H=40)=>`<g class="wave"><rect x="${f1(sx-.2*W)}" y="${f1(sy-.9*H)}" width="${W}" height="${H}" fill="none"/>${inner}</g>`;
