/* ================= FİL (yavru fil, mavi-gri; 3/4 sağa bakar, dört ayak) ================= */
const EB={base:"#A3B6CE",dark:"#5F7394",line:dk("#A3B6CE",.52),hi:"#E2ECF8",far:"#8A9EBB"};
const EP={base:"#F4B9C3",dark:"#D98C9C"};
