/* sütun bacak: konik, diz şişkinliği, yuvarlak ayak + kavisli tırnaklar. near: üstü gövdeye maskeyle kaynar (üst kontur yok).
   x: bacak ortası, top: üst uç (gövde içinde), dx/lift: ayağın öne kayması / yerden kalkması */
function eLeg(x,top,far,o={}){const w=o.w||(far?15.4:17.4),hw=w/2,dx=o.dx||0,lift=o.lift||0,gi=gid();
  const S=(px,py)=>{const t=Math.max(0,Math.min(1,(py-top)/(0-top)));return [px+dx*t,py-lift*t*t]};
  const P=(px,py)=>{const q=S(px,py);return f1(q[0])+" "+f1(q[1])};
  const left=`M${P(x-hw,top)} C${P(x-hw-.3,top*.6)} ${P(x-hw-1,-19)} ${P(x-hw-.9,-13.6)} C${P(x-hw-.8,-9.4)} ${P(x-hw+.9,-7.6)} ${P(x-hw+.8,-5.2)} C${P(x-hw+.7,-3.2)} ${P(x-hw-.9,-2.6)} ${P(x-hw-.7,-1.3)} Q${P(x-hw-.5,0)} ${P(x-hw+2.2,0)}`;
  const right=`L${P(x+hw-2.2,0)} Q${P(x+hw+.5,0)} ${P(x+hw+.7,-1.3)} C${P(x+hw+.9,-2.6)} ${P(x+hw-.7,-3.2)} ${P(x+hw-.8,-5.2)} C${P(x+hw-.9,-7.6)} ${P(x+hw+.8,-9.4)} ${P(x+hw+.9,-13.6)} C${P(x+hw+1,-19)} ${P(x+hw+.3,top*.6)} ${P(x+hw,top)}`;
  const d=left+right+"Z",open=left+right;
  const b=far?EB.far:EB.base,lo=far?mix(EB.far,"#FFFFFF",.18):EB.hi,hi2=far?mix(EB.far,EB.dark,.45):mix(EB.base,EB.dark,.55);
  const grad=`<linearGradient id="${gi}g" x1="0" y1="0" x2="1" y2="0"><stop offset="0" stop-color="${mix(b,lo,.35)}"/><stop offset=".38" stop-color="${b}"/><stop offset="1" stop-color="${hi2}"/></linearGradient>`;
  /* yakın bacak maskesi: gövdenin içine doğru yumuşakça kaybolur (gövde kenarında tam görünür → kontur kesişmesi yok) */
  const fade=far||!o.core?"":`<mask id="${gi}m" maskUnits="userSpaceOnUse" x="-120" y="-160" width="260" height="200"><rect x="-120" y="-160" width="260" height="200" fill="#fff"/><g filter="${u("soft2")}">${o.core}</g></mask>`;
  const q=(px,py)=>S(px,py);
  const wr=[-12.4,-10.2].map((yy,k)=>{const a=q(x-hw+2.4,yy),c=q(x+hw-2.6,yy),m=q(x,yy+1.6-k*.2);return `M${f1(a[0])} ${f1(a[1])} Q${f1(m[0])} ${f1(m[1])} ${f1(c[0])} ${f1(c[1])}`}).join(" ");
  const nails=(far?[-.18,.18]:[-.3,0,.3]).map(k=>{const c=q(x+k*w*.95,-.6);return `<path d="M${f1(c[0]-2.3)} ${f1(c[1]+.1)} C${f1(c[0]-2.2)} ${f1(c[1]-3)} ${f1(c[0]+2.2)} ${f1(c[1]-3)} ${f1(c[0]+2.3)} ${f1(c[1]+.1)} Q${f1(c[0])} ${f1(c[1]+.7)} ${f1(c[0]-2.3)} ${f1(c[1]+.1)}Z" fill="${far?"#DAD3CA":NAIL}" stroke="${EB.line}" stroke-width=".55"/><path d="M${f1(c[0]-1.1)} ${f1(c[1]-1.6)} q.8 -.6 1.8 -.3" stroke="#fff" stroke-width=".5" fill="none" opacity=".8" stroke-linecap="round"/>`}).join("");
  const hl=`<path d="M${P(x-hw+2.2,-24)} C${P(x-hw+1.6,-16)} ${P(x-hw+2.6,-10)} ${P(x-hw+2.4,-5)}" stroke="${far?lo:"#F2F7FD"}" stroke-width="1.6" fill="none" opacity="${far?.3:.55}" stroke-linecap="round" filter="${u("soft2")}"/>`;
  const body=`<path d="${d}" fill="url(#${gi}g)"/>${hl}<path d="${wr}" stroke="${EB.dark}" stroke-width=".8" fill="none" opacity="${far?.3:.45}" stroke-linecap="round"/><path d="${open}" fill="none" stroke="${EB.line}" stroke-width="${far?1.1:1.3}" stroke-linejoin="round" stroke-linecap="round" opacity="${far?.85:1}"/>${nails}`;
  const topSh=far?"":soft(`<ellipse cx="${f1(x+dx*.15)}" cy="${f1(top+(o.shy||9))}" rx="${f1(hw*1.05)}" ry="3.4" fill="${EB.dark}"/>`,.35);
  return `<defs>${grad}</defs>${fade}${far||!o.core?body+topSh:`<g mask="url(#${gi}m)">${body}${topSh}</g>`}`}
/* oturan arka bacak: izleyiciye dönük ayak tabanı (yer çizgisinde) */
function eSole(x,y,r){return `<g transform="translate(${x} ${y})">${vol(E1(0,0,r,r*1.02),{base:EB.base,dark:EB.dark,sx:-2,sy:-2,line:EB.line,lw:1.3,b:"soft2"})}<ellipse cx="${f1(r*.08)}" cy="${f1(r*.14)}" rx="${f1(r*.7)}" ry="${f1(r*.68)}" fill="#DCD2CB" stroke="${EB.line}" stroke-width=".6"/><path d="M${f1(-r*.3)} ${f1(r*.3)} q${f1(r*.3)} ${f1(r*.16)} ${f1(r*.6)} 0" stroke="#BFB3AA" stroke-width=".6" fill="none"/>${[-.56,0,.56].map(k=>`<path d="M${f1(k*r*.82-r*.19)} ${f1(-r*.6+Math.abs(k)*r*.28)} a${f1(r*.19)} ${f1(r*.17)} 0 0 1 ${f1(r*.38)} 0 q${f1(-r*.19)} ${f1(r*.08)} ${f1(-r*.38)} 0Z" fill="${NAIL}" stroke="${EB.line}" stroke-width=".5"/>`).join("")}</g>`}
/* eğik elips yolu */
