    const BC=[-11,-28,31.4,27.6,-23],bd=ellD(...BC),core=ellD(BC[0],BC[1],BC[2]-4,BC[3]-4,BC[4]);
    const body=vol(P1(bd),{base:EB.base,dark:EB.dark,sx:-6,sy:-7,line:EB.line,lw:1.45,hl:`<ellipse cx="-22" cy="-40" rx="11" ry="4.6" fill="${EB.hi}" opacity=".55" filter="${u("soft2")}" transform="rotate(-64 -22 -40)"/>`});
    const stail=`<path d="M-38 -9 C-44 -4 -50 -2.4 -56 -2.6" stroke="${EB.line}" stroke-width="3.8" fill="none" stroke-linecap="round"/><path d="M-38 -9 C-44 -4 -50 -2.4 -56 -2.6" stroke="${EB.base}" stroke-width="2.2" fill="none" stroke-linecap="round"/><path d="M-56 -2.6 l-4.4 -2.4 M-56 -2.6 l-5 .6 M-56 -2.6 l-4 2.8" stroke="#4A5670" stroke-width="1.6" stroke-linecap="round"/>`;
    const thigh=vol(P1(ellD(-17,-14.6,15.4,12.4,-10)),{base:EB.base,dark:EB.dark,sx:-3,sy:-4,line:EB.line,lw:1.3,b:"soft2",hl:`<path d="M-29 -20 q6 -7.6 18 -6.8" stroke="${EB.hi}" stroke-width="1.6" fill="none" opacity=".6" stroke-linecap="round"/>`});
