    const body=vol(E1(...BC),{base:EB.base,dark:EB.dark,sx:-6,sy:-7,line:EB.line,lw:1.45,rim:EB.hi,hl:`<ellipse cx="-20" cy="-64" rx="14" ry="5" fill="${EB.hi}" opacity=".55" filter="${u("soft2")}"/>`});
    const belly=soft(`<path d="M-36 -26 C-24 -19 0 -19 12 -26" stroke="${EB.dark}" stroke-width="3" fill="none"/>`,.3)+`<path d="M-34 -52 q-2.4 6 0 12 M-38 -48 q-1.6 4 0 8 M4 -56 q2 5 0 10" stroke="${EB.dark}" stroke-width=".9" fill="none" opacity=".35" stroke-linecap="round"/>`;
