    `<path d="M${F(x+side*r*.9)} ${F(y+r*.12)} l${F(side*r*.32)} ${F(r*.16)}" stroke="${arc}" stroke-width="${F(r*.18)}" stroke-linecap="round"/>`;
  if(m==="happy")return `<path d="M${F(x-r)} ${F(y+r*.3)} Q${F(x)} ${F(y-r*1.15)} ${F(x+r)} ${F(y+r*.3)}" stroke="${arc}" stroke-width="${lw}" fill="none" stroke-linecap="round"/>`;
  if(m==="closed"){const xo=x+side*r;return `<path d="M${F(x-r)} ${F(y)} Q${F(x)} ${F(y+r*.9)} ${F(x+r)} ${F(y)}" stroke="${arc}" stroke-width="${lw}" fill="none" stroke-linecap="round"/>`+
    (E.lash?`<path d="M${F(xo)} ${F(y)} l${F(side*r*.5)} ${F(-r*.28)} M${F(xo-side*r*.28)} ${F(y+r*.4)} l${F(side*r*.42)} ${F(r*.12)}" stroke="${arc}" stroke-width="${F(r*.22)}" stroke-linecap="round"/>`:"")}
  const [lx,ly]=M.look||[0,0];
