function bodyG(d,G,dy){return `<clipPath id="${G}b"><path d="${d}"/></clipPath>${vol(P1(d),{base:K.base,dark:K.dark,sx:-5,sy:-7,hl:`<ellipse cx="-16" cy="${-66+dy}" rx="11" ry="3.2" fill="#fff" filter="${u("soft2")}"/>`})}<g clip-path="url(#${G}b)">${spotsG(dy,G)}${soft(`<path d="M-30 ${-33+dy} C-18 ${-26+dy} 14 ${-25+dy} 30 ${-35+dy} C22 ${-31+dy} 6 ${-30.4+dy} -4 ${-30.6+dy} C-16 ${-30.8+dy} -24 ${-31.6+dy} -30 ${-33+dy}Z" fill="#1A1030"/>`,.16)}${soft(`<path d="M-24.6 ${-64+dy} C-21 ${-69+dy} -15 ${-70+dy} -11 ${-67.4+dy}" stroke="#1A1030" stroke-width="2.4" fill="none" stroke-linecap="round"/>`,.12)}</g><path d="${d}" fill="none" stroke="${K.line}" stroke-width="1.45" stroke-linejoin="round"/>`}
