  const defs=`<defs>${LG(G+"l",[[0,"#FFFFFF"],[1,K.dark]],0,0,1,0)}${LG(G+"f",[[0,mix(K.base,K.dark,.7)],[1,mix(K.dark,K.line,.35)]],0,0,1,0)}${RG(G+"i",[[0,"#C99A6E"],[.55,"#6A4226"],[1,"#2E1C12"]],.5,.66,.62)}${RG(G+"e",[[0,"#FFC8D2"],[1,"#EC95A8"]],.8,.5,.7)}</defs>`;
