  const body=`${vol(P1(bd),{base:SC.base,dark:SC.dark,sx:2.4,sy:2.8,line:SC.line,lw:1.4,b:"soft2"})}<clipPath id="${bc}"><path d="${bd}"/></clipPath><g clip-path="url(#${bc})">${speck}${ripples}<path d="${ruf}" stroke="${lt(SC.base,.45)}" stroke-width="1.5" fill="none" stroke-linecap="round" opacity=".6" filter="${u("soft2")}"/><path d="${ruf}" stroke="${lt(SC.base,.3)}" stroke-width=".6" fill="none" stroke-linecap="round" opacity=".55"/><path d="M${tail+7} -2.2 C-10 -2.9 0 -2.9 ${12+dx} -2.4" stroke="#FFFFFF" stroke-width=".5" fill="none" stroke-linecap="round" opacity=".45"/><path d="M${20.6+dx} -12.6 q2 .6 3.4 -.2 M${21.4+dx} -9.4 q1.8 .5 3 -.2" stroke="${SC.dark}" stroke-width=".7" fill="none" opacity=".55" stroke-linecap="round"/>${glint(-16,-4.4,5,1.1,.55,-6)}</g>`;
