  bubbles:(x,y,z)=>`<g class="float">${[[0,0,.2],[z*.5,-z*.6,.3],[z*1.2,-z*1.5,.5]].map(([dx,dy,r])=>`<circle cx="${f1(x+dx)}" cy="${f1(y+dy)}" r="${f1(z*r)}" fill="#FFFFFF" stroke="#A9B8D8" stroke-width="${f1(z*.07)}"/>`).join("")}</g>`,
  burst:(x,y,z,c)=>[28,62,96].map(a=>{const r=a*Math.PI/180;return `<path d="M${f1(x+Math.sin(r)*z*.9)} ${f1(y-Math.cos(r)*z*.9)} L${f1(x+Math.sin(r)*z*1.6)} ${f1(y-Math.cos(r)*z*1.6)}" stroke="${c||"#F2A21E"}" stroke-width="${f1(z*.16)}" stroke-linecap="round"/>`}).join(""),
