  anger:(x,y,z)=>`<g class="beat"><path d="M${f1(x-z*.5)} ${f1(y-z*.15)} q${f1(z*.35)} ${f1(-z*.05)} ${f1(z*.35)} ${f1(-z*.4)} M${f1(x+z*.5)} ${f1(y-z*.15)} q${f1(-z*.35)} ${f1(-z*.05)} ${f1(-z*.35)} ${f1(-z*.4)} M${f1(x-z*.5)} ${f1(y+z*.15)} q${f1(z*.35)} ${f1(z*.05)} ${f1(z*.35)} ${f1(z*.4)} M${f1(x+z*.5)} ${f1(y+z*.15)} q${f1(-z*.35)} ${f1(z*.05)} ${f1(-z*.35)} ${f1(z*.4)}" fill="none" stroke="#E0463E" stroke-width="${f1(z*.16)}" stroke-linecap="round"/></g>`,
  shyL:(x,y,z)=>`<path d="M${f1(x-z*.5)} ${f1(y+z*.2)} l${f1(z*.25)} ${f1(-z*.4)} M${f1(x-z*.1)} ${f1(y+z*.2)} l${f1(z*.25)} ${f1(-z*.4)} M${f1(x+z*.3)} ${f1(y+z*.2)} l${f1(z*.25)} ${f1(-z*.4)}" stroke="#E0567A" stroke-width="${f1(z*.1)}" stroke-linecap="round" opacity=".7"/>`,
  joy:(x,y,z)=>`<path d="M${f1(x)} ${f1(y-z)} Q${f1(x+z*.12)} ${f1(y-z*.12)} ${f1(x+z)} ${f1(y)} Q${f1(x+z*.12)} ${f1(y+z*.12)} ${f1(x)} ${f1(y+z)} Q${f1(x-z*.12)} ${f1(y+z*.12)} ${f1(x-z)} ${f1(y)} Q${f1(x-z*.12)} ${f1(y-z*.12)} ${f1(x)} ${f1(y-z)}Z" fill="#FFE680" stroke="#E9A21F" stroke-width="${f1(z*.08)}"/>`
