  scene(t){const I={spring:{k:"cicek-demeti",s:1.3,dy:-6},summer:{k:"kova-kurek",s:1.2},autumn:{k:"yaprak",s:1.8,color:"orange",shape:"maple"},winter:{k:"kardan-adam",s:.5}};const order=shuf(Object.keys(I));
    return {sc:{set:"orman",time:"day",season:t,props:order.map((s,i)=>({...I[s],x:[80,160,240,330][i],y:236+(I[s].dy||0),hit:"m-"+s}))},say:"mevsim-soru",text:EN_("Hangi mevsim? Uygun olana dokun!","Which season? Tap the matching thing!"),first:null}},
