/* =====================================================================
   Ebeveyn kilidi (Apple Çocuklar kategorisi 1.3 / Google Aileler politikası):
   dış bağlantılar yalnız yetişkin doğrulamasından sonra açılır.
   Soru: yazıyla verilen iki basamaklı sayıyı rakamla yazmak (okuma bilmeyen çocuk geçemez).
   ===================================================================== */
const GATE={
  N:["","bir","iki","üç","dört","beş","altı","yedi","sekiz","dokuz"],T:["","on","yirmi","otuz","kırk","elli","altmış","yetmiş","seksen","doksan"],
  NE:["","one","two","three","four","five","six","seven","eight","nine"],TE:["","ten","twenty","thirty","forty","fifty","sixty","seventy","eighty","ninety"],
  ask(onOk){const en=typeof S!=="undefined"&&S.lang==="en",n=23+Math.floor(Math.random()*70),w=en?(this.TE[Math.floor(n/10)]+(n%10?"-"+this.NE[n%10]:"")):(this.T[Math.floor(n/10)]+" "+this.N[n%10]).trim();
    const t=en?{h:"Grown-ups only",p:"To continue, type this number in digits:",n:"Number",e:"Not quite. Please try again.",c:"Cancel",o:"Continue"}:{h:"Ebeveyn onayı",p:"Devam etmek için bu sayıyı rakamla yazın:",n:"Sayı",e:"Yanlış. Lütfen tekrar deneyin.",c:"Vazgeç",o:"Devam"};
    const d=document.createElement("div");d.className="gate";d.setAttribute("role","dialog");d.setAttribute("aria-modal","true");d.setAttribute("aria-labelledby","gate-h");
    d.innerHTML=`<div class="gate-card"><h3 id="gate-h">${t.h}</h3><p>${t.p}</p><p class="gate-q">${w}</p>
      <input id="gate-in" inputmode="numeric" pattern="[0-9]*" maxlength="3" autocomplete="off" aria-label="${t.n}"><p class="gate-err" hidden>${t.e}</p>
      <div class="gate-row"><button type="button" class="gate-no">${t.c}</button><button type="button" class="gate-ok">${t.o}</button></div></div>`;
    document.body.appendChild(d);const inp=d.querySelector("#gate-in");setTimeout(()=>inp.focus(),50);
    const close=()=>d.remove();
    d.querySelector(".gate-no").onclick=close;d.onclick=e=>{if(e.target===d)close()};
    const ok=()=>{if(+inp.value===n){close();onOk()}else{d.querySelector(".gate-err").hidden=false;inp.value="";inp.focus()}};
    d.querySelector(".gate-ok").onclick=ok;inp.onkeydown=e=>{if(e.key==="Enter")ok();if(e.key==="Escape")close()}},
  open(url){this.ask(()=>{window.open(url,"_blank","noopener")})}};
document.addEventListener("click",e=>{const a=e.target.closest&&e.target.closest('a[href^="http"]');if(!a)return;e.preventDefault();GATE.open(a.href)},true);

/* =====================================================================
   Envato ses paketi (isteğe bağlı): app/envato/{sfx,amb,muzik}/*.mp3
   build.py dosyaları envato/manifest.json'a yazar. Dosya varsa:
   - AU.sfx(ad) sentez yerine gerçek kaydı çalar,
   - her sayfada mekâna göre ortam sesi (amb) döngüde çalar,
   - masal boyunca fon müziği (muzik) çalar; anlatım sırasında kısılır.
   Dosya yoksa her şey eskisi gibi çalışır.
   ===================================================================== */
const EV={m:null,amb:null,mus:null,g:{},
  async init(){try{const r=await fetch("envato/manifest.json");if(r.ok)this.m=await r.json()}catch(e){}},
  has(t,n){return !!(this.m&&this.m[t]&&this.m[t].includes(n))},
  bus(name,v){const c=AU.ctx;if(!c)return null;if(!this.g[name]){const g=c.createGain();g.gain.value=v;g.connect(c.destination);this.g[name]={g,v}}return this.g[name].g},
  async loop(slot,path,bus,vol){const cur=this[slot];if(cur&&cur.path===path)return;this.stopSlot(slot);if(!path||!AU.ctx)return;
    const tok={};this[slot+"Tok"]=tok;const buf=await AU.load(path);if(!buf||this[slot+"Tok"]!==tok)return;
    const c=AU.ctx,src=c.createBufferSource(),v=c.createGain();src.buffer=buf;src.loop=true;v.gain.setValueAtTime(.0001,c.currentTime);
    v.gain.exponentialRampToValueAtTime(1,c.currentTime+1.2);src.connect(v).connect(this.bus(bus,vol));src.start();this[slot]={src,v,path}},
  stopSlot(slot){const s=this[slot];if(!s)return;this[slot]=null;const c=AU.ctx;try{s.v.gain.setTargetAtTime(.0001,c.currentTime,.25);s.src.stop(c.currentTime+1)}catch(e){}},
  stopAll(){this.ambTok=this.musTok=null;this.stopSlot("amb");this.stopSlot("amb2");this.stopSlot("mus")},
  ambFor(sc){if(!sc)return[];const night=/night|evening/.test(sc.time||""),s=sc.set||"cayir";let k=night&&this.has("amb",s+"-gece")?s+"-gece":s;
    if(!this.has("amb",k))k=s;
    if(!this.has("amb",k)){const ins=/salon|sinif|mutfak|banyo|oda-gece|saglik-ocagi/.test(s);k=ins?(night?"oda-gece":"salon"):(night?"cayir-gece":"cayir")}
    if(!this.has("amb",k))k=null;
    const e=sc.weather==="rain"?"yagmur":sc.weather==="snow"?"kar":null;return[k,this.has("amb",e)?e:null]},
  musicFor(s){if(s.muzik)return s.muzik;const t=((s.trTitle||s.title||"")+" "+(s.trTheme||s.theme||"")+" "+(s.trBlurb||s.blurb||"")).toLocaleLowerCase("tr");
    if(/uyku|ninni|gece/.test(t))return"ninni";if(/bayram|23 nisan|şenlik/.test(t))return"kutlama";if(s.area==="Müzik")return"ritim";
    if(/kıskan|taşın|üzül|kayıp|yara|korku|özür/.test(t))return"duygusal";if(/nefes|sakin|yavaş|sabır/.test(t))return"sakin";
    if(s.area==="Fen"||s.area==="Matematik")return"merak";if(s.area==="Hareket ve Sağlık")return"macera";return"neseli"},
  page(){if(!this.m||!S.fx||!AU.ctx||typeof R==="undefined"||!R.s){this.stopAll();return}
    const pg=R.s.pages&&R.s.pages[R.i];const [a,b]=this.ambFor(pg&&(pg.scene||pg.sc));
    this.loop("amb",a&&"envato/amb/"+a+".mp3","amb",.16);this.loop("amb2",b&&"envato/amb/"+b+".mp3","amb",.16);
    const mu=this.musicFor(R.s);this.loop("mus",this.has("muzik",mu)&&"envato/muzik/"+mu+".mp3","mus",.11)},

  /* anlatım ipuçları: sayfa metnindeki ses sözcüğü okunduğu anda efekt (pages[i].cues=[{w,fx}]) */
  cue(n){if(!S.fx||!AU.ctx)return;if(!this.has("sfx",n))return AU.sfx(n);const c=AU.ctx;
    AU.load("envato/sfx/"+n+".mp3").then(b=>{if(!b)return;const s=c.createBufferSource(),g=c.createGain();g.gain.value=.6;s.buffer=b;s.connect(g).connect(AU.fxg);s.start()})},
  duck(){const c=AU.ctx;if(!c)return;const on=AU.busy;for(const k in this.g){const b=this.g[k];b.g.gain.setTargetAtTime(on?b.v*.35:b.v,c.currentTime,.3)}}};
(function(){
  const synth=AU.sfx.bind(AU);
  AU.sfx=function(n){if(!S.fx||!this.ctx)return;if(!EV.has("sfx",n))return synth(n);
    const c=this.ctx;this.load("envato/sfx/"+n+".mp3").then(b=>{if(!b)return synth(n);const s=c.createBufferSource();s.buffer=b;s.connect(this.fxg);s.start()})};
  const play=AU.play.bind(AU);
  AU.play=function(id,o={}){try{const pg=typeof R!=="undefined"&&R.s&&R.s.pages&&R.s.pages[R.i];
      if(o.onWord&&pg&&pg.cues&&pg.cues.length&&String(id).endsWith("/p"+R.i)){const done=new Set(),ow=o.onWord;
        o=Object.assign({},o,{onWord:k=>{ow(k);for(const c of pg.cues)if(k>=c.w&&!done.has(c)){done.add(c);EV.cue(c.fx)}}})}}catch(e){}
    return play(id,o)};
  const rr=renderReader;renderReader=function(){const r=rr.apply(this,arguments);try{EV.page()}catch(e){}return r};
  EV.init();setInterval(()=>{const rd=document.querySelector("#reader");if(EV.m&&(!rd||rd.hidden))EV.stopAll();else EV.duck()},300);
})();

/* =====================================================================
   Envato görsel paketi (isteğe bağlı): app/envato/gorsel/arkaplan/
     {salon,mutfak,banyo}.jpg (okuyucu, 2000x1200) · {set}-k.jpg (küçük: kapak, tahmin kartı, sıralama oyunu)
     salon-cam.png (pencere camı maskesi) · geo.json (sahne birimlerinde geometri) — tools/gorsel_prep.py üretir.
   build.py dosyaları dist/envato/gorsel/arkaplan'a kopyalar, manifest.json'a "gorsel":{"arkaplan":[...]} yazar ve
   her masal için hangi mekânların fotoğrafla çizilebileceğini hesaplar (catalog.json ve stories/*.json: "photo":[...]).
   img içindeki SVG dış dosya yükleyemez: görseller bir kez data: URL'ye çevrilir (fetch → blob → FileReader).
   Okuyucu açılmadan önce beklenir (en çok 4 sn). Yüklenemezse mekân kod çizimiyle kalır; açık bir masalın ortasında
   geç gelen görsel devreye girmez (masal kapanınca etkinleşir) — bir masal aynı odayı hiç karışık çizmez.
   ===================================================================== */
const PHL={ready:null,pending:null};
(function(){
  const base="envato/gorsel/arkaplan/";
  const toData=u=>fetch(u).then(r=>{if(!r.ok)throw new Error(u);return r.blob()})
    .then(b=>new Promise((res,rej)=>{const f=new FileReader();f.onload=()=>res(f.result);f.onerror=rej;f.readAsDataURL(b)}));
  const readerOpen=()=>{const r=document.querySelector("#reader");return !!(r&&!r.hidden)};
  const commit=()=>{if(!PHL.pending)return;if(readerOpen())return setTimeout(commit,500);Object.assign(PH,PHL.pending);PHL.pending=null;redrawCovers()};
  PHL.ready=(async()=>{try{
    const r=await fetch("envato/manifest.json");if(!r.ok)return;const m=await r.json();
    const sets=(m.gorsel&&m.gorsel.arkaplan)||[];if(!sets.length)return;
    const geo=await (await fetch(base+"geo.json")).json(),got={};
    await Promise.all(sets.map(async s=>{try{const g=geo[s];if(!g)return;
      const [full,small,mask]=await Promise.all([toData(base+s+".jpg"),toData(base+s+"-k.jpg"),g.glass?toData(base+s+"-cam.png"):null]);
      got[s]={geo:g,full,small,mask,ok:true}}catch(e){console.warn("görsel yüklenemedi:",s,e)}}));
    PHL.pending=got;commit();
  }catch(e){}})();
  /* masal JSON'u: fotoğrafla çizilecek mekânların sahnelerini (sayfa + tahmin seçenekleri) işaretle */
  const mark=j=>{const ps=new Set(j.photo||[]);if(!ps.size)return;
    (j.pages||[]).forEach(p=>[p.scene,...((p.predict&&p.predict.opts)||[]).map(o=>o.scene)].forEach(sc=>{if(sc&&ps.has(sc.set))sc.photo=true}))};
  const hy=hydrate;hydrate=function(j){try{mark(j)}catch(e){}return hy.apply(this,arguments)};
  /* katalog kapağı: kapak sahnesi masalın ilk sayfası; masal o mekânda fotoğraflıysa kapak da öyle (küçük görsel) */
  const dc=drawCover;drawCover=function(el){const s=catById(el.dataset.cover);if(s&&s.cover&&(s.photo||[]).includes(s.cover.set))s.cover.photo=true;return dc.apply(this,arguments)};
  function redrawCovers(){document.querySelectorAll("[data-cover]").forEach(el=>{const s=catById(el.dataset.cover);
    if(!s||!s.cover||!(s.photo||[]).includes(s.cover.set))return;const sc=el.querySelector(".scene");if(sc){sc.remove();drawCover(el)}})}
  const or=openReader;openReader=async function(){await Promise.race([PHL.ready,new Promise(r=>setTimeout(r,4000))]);if(PHL.pending&&!readerOpen())commit();return or.apply(this,arguments)};
})();

/* =====================================================================
   Yapay zekâ ile boyanmış masal sayfaları (ElevenLabs · GPT Image 2)
   app/ai/<masal-id>/ai-<sayfa>.webp  (1200x720, sahnenin 400x240 karesiyle birebir)
                     sp-<anahtar>.webp (taşınan nesne: şeffaf zeminli)
                     meta.json        {"sp":{"<sayfa>":["anahtar",...]}}
   build.py bunları dist/ai'ye kopyalar ve ai/manifest.json yazar: {id:{pages:[...],sp:{...}}}.
   Kod çizimi silinmez: sahne her zamanki gibi kurulur (dokunma alanları, kamera, mekanikler aynen çalışır),
   yalnız görünümü saydamlaşır; arka plana resim, taşınan nesnelere resim konur.
   ===================================================================== */
const AIM={},AIPACK={};
(function(){
  /* resimler paketlerden data: URL olarak gelir (claude.ai dosya sınırı): ortak + kapak açılışta, masal paketi masal açılınca */
  const PK={};const loadPack=u=>PK[u]||(PK[u]=fetch(u).then(r=>r.ok?r.json():{}).then(j=>Object.assign(AIPACK,j)).catch(()=>{}));
  /* manifest, ortak ve kapak paketleri inince etkinleşir (öncesinde kod çizimi kalır; yarım yüklemede kırık resim olmaz) */
  /* yükleme bitene kadar kapaklar gizli (eski çizim bir an bile görünmesin); hata olursa da açılır */
  document.documentElement.classList.add("aiwait");
  const ready=fetch("ai/manifest.json").then(r=>r.ok?r.json():{}).then(async m=>{
    await Promise.all([m._ortak,m._kapak].filter(Boolean).map(loadPack));Object.assign(AIM,m)}).catch(()=>{});
  const U=p=>AIPACK[p]||p;
  const base=id=>`ai/${id}/`;
  const ofPage=(id,i)=>{const m=AIM[id];return m&&m.pages&&m.pages.includes(i)?m:null};
  const hasSp=k=>(AIM._sprites||[]).includes(k);
  const isAi=()=>{const s=document.querySelector("#art .scene:not(.out)");return !!(s&&s.classList.contains("ai"))};
  function apply(el,id,i){const m=ofPage(id,i);if(!el||!m)return;if(m.pack&&!AIPACK[base(id)+`ai-${i}.webp`])return;/* paket yüklenemedi: kod çizimi */el.classList.add("ai");
    const svg=el.querySelector("svg.L-fg"),img=el.querySelector("img.L-bg");
    const [vx,vy,vw,vh]=(svg.getAttribute("viewBox")||"0 0 400 240").split(/[\s,]+/).map(Number);
    img.src=U(base(id)+`ai-${i}.webp`);
    Object.assign(img.style,{inset:"auto",left:(-vx/vw*100)+"%",top:(-vy/vh*100)+"%",width:(400/vw*100)+"%",height:(240/vh*100)+"%",objectFit:"fill"});
    ((m.sp||{})[i]||[]).forEach(k=>el.querySelectorAll(`[data-hit="${k}"]`).forEach(h=>{const g=h.tagName==="g"?h:h.parentNode;let b;try{b=h.getBBox()}catch(e){return}
      if(!b.width&&!b.height)return;const im=document.createElementNS("http://www.w3.org/2000/svg","image");
      im.setAttribute("class","aisp");im.setAttribute("href",U(base(id)+`sp-${k}.webp`));const pad=Math.max(b.width,b.height)*.08;
      im.setAttribute("x",b.x-pad);im.setAttribute("y",b.y-pad);im.setAttribute("width",b.width+2*pad);im.setAttribute("height",b.height+2*pad);
      im.setAttribute("preserveAspectRatio","xMidYMid meet");g.appendChild(im)}));
    /* hareketli öğeler (toplanan, ayrılan, yürüyen, büyüyen…): arka planda yok; karakterse kart resmi, nesne resmi varsa o, yoksa kod çizimi görünür */
    ((m.dyn||{})[i]||[]).forEach(k=>el.querySelectorAll(`.L-fgc [data-hit="${k}"]`).forEach(h=>{
      const cm=h.closest(".cm"),pk=h.closest("[data-pk]");
      if(cm&&hasSp("c-"+cm.dataset.k))spriteInto(cm,`ai/sprite/c-${cm.dataset.k}.webp`);
      else if(!cm&&!pk&&hasSp("c-"+k))spriteInto(h,`ai/sprite/c-${k}.webp`);/* eski masallar: karakter sarmalayıcısı yok */
      else if(pk&&hasSp(pk.dataset.pk)&&!h.querySelector(".gs,.flower,.st"))spriteInto(pk,`ai/sprite/${pk.dataset.pk}.webp`);
      else (cm||pk||h).classList.add("aikeep")}))}
  /* okuyucu: sahne kurulup kamera kadrajı belirlendikten sonra */
  const rr=renderReader;renderReader=function(){const r=rr.apply(this,arguments);try{if(R.phase==="page"&&R.s)apply(document.querySelector("#art .scene:not(.out)"),R.s.id,R.i)}catch(e){console.warn(e)}return r};
  /* görünmez öğeler için görünür ipucu: nabız halkası ve dokunuş pırıltısı */
  const ring=k=>{const e=hitEl(k),s=svgEl();if(!e||!s)return;const b=camBox(e,s.querySelector(".L-fgc"));if(!b)return;
    const r=document.createElementNS("http://www.w3.org/2000/svg","ellipse");r.setAttribute("class","airing");
    r.setAttribute("cx",(b.x1+b.x2)/2);r.setAttribute("cy",(b.y1+b.y2)/2);r.setAttribute("rx",(b.x2-b.x1)/2+6);r.setAttribute("ry",(b.y2-b.y1)/2+6);s.appendChild(r)};
  const pu=pulse;pulse=function(k){pu.apply(this,arguments);document.querySelectorAll("#art .airing").forEach(x=>x.remove());if(isAi())ring(k)};
  const up=unpulse;unpulse=function(){up.apply(this,arguments);document.querySelectorAll("#art .airing").forEach(x=>x.remove())};
  const an=anim;anim=function(el,cls){an.apply(this,arguments);if(isAi()&&el&&!el.querySelector("image.aisp")&&el.closest&&el.closest("#art"))sparkAt(el,7)};
  /* oyun kaplaması: AI arka plan + nesne/karakter resimleri; resmi olmayan öğe kod çizimiyle kalır (aikeep) */
  /* oyunlar: sahnenin mekânına göre AI arka plan (ai/oyun/bg-<anahtar>.webp); öğeler nesne/karakter resmiyle, yoksa kod çizimiyle */
  const bgKey=sc=>[sc.set,sc.time&&sc.time!=="day"?sc.time:"",sc.season||"",sc.weather||""].filter(Boolean).join("-");
  const bgOf=sc=>{if(!sc)return null;const k=bgKey(sc),b=AIM._bg||[];return b.includes(k)?k:b.includes(sc.set)&&!sc.season&&!sc.weather&&(!sc.time||sc.time==="day")?sc.set:null};
  function spriteInto(g,url){const t=g.matches("[data-hit]")?g:(g.querySelector("[data-hit]")||g);const host=t.tagName==="g"?t:t.parentNode;const pads=[...g.querySelectorAll(".tpad")].map(e=>[e,e.parentNode,e.nextSibling]);pads.forEach(([e])=>e.remove());
    let b;try{b=g.getBBox()}catch(e){}pads.forEach(([e,p,n])=>p.insertBefore(e,n));if(!b)return;
    if(!b.width&&!b.height)return;let M=null;try{M=g.getCTM().inverse().multiply(host.getCTM())}catch(e){}
    const p=M?[[b.x,b.y],[b.x+b.width,b.y+b.height]].map(([x,y])=>new DOMPoint(x,y).matrixTransform(M.inverse())):[[b.x,b.y],[b.x+b.width,b.y+b.height]].map(([x,y])=>({x,y}));
    const im=document.createElementNS("http://www.w3.org/2000/svg","image");im.setAttribute("class","aisp");im.setAttribute("href",U(url));
    const x1=Math.min(p[0].x,p[1].x),y1=Math.min(p[0].y,p[1].y),w=Math.abs(p[1].x-p[0].x),h=Math.abs(p[1].y-p[0].y);
    im.setAttribute("x",x1);im.setAttribute("y",y1);im.setAttribute("width",w);im.setAttribute("height",h);im.setAttribute("preserveAspectRatio","xMidYMax meet");host.appendChild(im)}
  function skin(el,sc){if(!el||!sc||!AIM._ortak)return;const bg=bgOf(sc);if(!bg)return;el.classList.add("ai");
    const img=el.querySelector("img.L-bg");img.src=U(`ai/oyun/bg-${bg}.webp`);Object.assign(img.style,{objectFit:"cover"});
    el.querySelectorAll(".L-fgc [data-pk]").forEach(g=>{const k=g.dataset.pk;if(k==="tree"&&!g.querySelector("[data-hit]"))return;/* dekor ağacı: arka planda zaten ağaç var */if(!g.dataset.pv&&hasSp(k)&&!g.querySelector("[data-pk]"))spriteInto(g,`ai/sprite/${k}.webp`);else g.classList.add("aikeep")});
    el.querySelectorAll(".L-fgc .cm[data-k]").forEach(g=>{const k=g.dataset.k;if(!g.dataset.pv&&hasSp("c-"+k))spriteInto(g,`ai/sprite/c-${k}.webp`);else g.classList.add("aikeep")})}
  ready.then(()=>{if(typeof renderGames==="function"&&document.querySelector("#games [data-game]"))renderGames()});
  const grr=GAME.renderRound;GAME.renderRound=function(){const r=grr.apply(this,arguments);try{skin(document.querySelector("#game #art .scene"),this.cur&&this.cur.sc)}catch(e){console.warn(e)}return r};
  const rg=renderGames;renderGames=function(){const r=rg.apply(this,arguments);document.querySelectorAll("#games [data-game]").forEach(c=>{const g=GAMES.find(x=>x.id===c.dataset.game);if(g)skin(c.querySelector(".scene"),g.cover)});return r};
  /* kapaklar: kütüphane kartı ve masal sayfası (sheet) */
  const coverImg=id=>`<div class="scene ai"><img class="L-bg" alt="" draggable="false" src="${AIPACK[base(id)+"kapak.webp"]||U(base(id)+"ai-0.webp")}"></div>`;
  const dc=drawCover;drawCover=function(el){const id=el.dataset.cover;if(ofPage(id,0)){if(!el.querySelector(".scene"))el.insertAdjacentHTML("afterbegin",coverImg(id));return}return dc.apply(this,arguments)};
  const os=openSheet;openSheet=async function(id){const r=await os.apply(this,arguments);if(ofPage(id,0)){const h=document.querySelector("#sheet .hero .scene");if(h)h.outerHTML=coverImg(id)}return r};
  const or=openReader;openReader=async function(id){await Promise.race([ready,new Promise(r=>setTimeout(r,3000))]);
    const m=AIM[id];if(m&&m.pack)await Promise.race([loadPack(m.pack),new Promise(r=>setTimeout(r,8000))]);return or.apply(this,arguments)};
  ready.finally(()=>setTimeout(()=>document.documentElement.classList.remove("aiwait"),50));
  ready.then(()=>document.querySelectorAll("[data-cover]").forEach(el=>{if(!ofPage(el.dataset.cover,0))return;const s=el.querySelector(".scene");if(s){s.remove();drawCover(el)}}));
})();

/* =====================================================================
   İki uygulama, tek kaynak: NOVA ECE Masal (data-app="masal") ve NOVA ECE Oyun (data-app="oyun").
   build.py dist/ (masal) ve dist-oyun/ (oyun) üretir; index.html <html data-app> ile hangisi olduğunu söyler.
   Masal: kitaplık + okuyucu; oyun rafının yerinde Oyun uygulamasına bağlantı. Oyun: yalnız oyun rafı; masal uygulamasına bağlantı.
   ===================================================================== */
const APP=document.documentElement.dataset.app||"masal";
const OYUN_URL=LINK('/oyun/','https://claude.ai/artifact/F78F21YY6SQ4BcGMrTpi6W'),MASAL_URL=LINK('/masal/','https://claude.ai/artifact/HpvhvYR4r28dQJNzGJwvpP');
(function(){
  const promo=()=>{const en=S.lang==="en";
    return APP==="masal"
      ?`<a class="app-promo" href="${OYUN_URL}" target="_blank" rel="noopener"><span class="ap-ic" aria-hidden="true">🎲</span><span><b>${en?"100 learning games":"100 eğitsel oyun"}</b><span>${en?"Counting, patterns, first sounds, colors and feelings with the same characters: NOVA ECE Games.":"Aynı karakterlerle sayma, örüntü, ilk ses, renk ve duygular: NOVA ECE Oyun."}</span></span><span class="ap-go" aria-hidden="true">›</span></a>`
      :`<a class="app-promo" href="${MASAL_URL}" target="_blank" rel="noopener"><span class="ap-ic" aria-hidden="true">📖</span><span><b>${en?"100 interactive stories":"100 etkileşimli masal"}</b><span>${en?"Narrated picture books where children touch, count and guess: NOVA ECE Stories.":"Dokunarak, sayarak ve tahmin ederek okunan sesli resimli masallar: NOVA ECE Masal."}</span></span><span class="ap-go" aria-hidden="true">›</span></a>`};
  if(APP==="masal"){renderGames=function(){const h=$("#games");if(h)h.innerHTML=promo()}}
  else{const rg=renderGames;renderGames=function(){const r=rg.apply(this,arguments);const h=$("#games");if(h&&!h.querySelector(".app-promo"))h.insertAdjacentHTML("beforeend",promo());return r};
    document.title="NOVA ECE Oyun";const pr=document.querySelector(".brand .prod");if(pr)pr.textContent="Oyun";
    const br=document.querySelector(".brand");if(br)br.setAttribute("aria-label","NOVA ECE Oyun — novaece.com")}
})();
